import{_ as o,o as d,c,a6 as t}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"版本 Changelog","description":"从 1.0 GA 到 2.1.318 的关键里程碑（精选，非逐条流水账），着重梳理近期逐版本变化","frontmatter":{"title":"版本 Changelog","description":"从 1.0 GA 到 2.1.318 的关键里程碑（精选，非逐条流水账），着重梳理近期逐版本变化","source":"https://daiw.org/manual/claude-code/changelog"},"headers":[],"relativePath":"manual/agent/claude-code/changelog.md","filePath":"manual/agent/claude-code/changelog.md"}'),l={name:"manual/agent/claude-code/changelog.md"};function a(s,e,r,n,i,g){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="版本-changelog" tabindex="-1">版本 Changelog <a class="header-anchor" href="#版本-changelog" aria-label="Permalink to &quot;版本 Changelog&quot;">​</a></h1><blockquote><p>从 1.0 GA 到 2.1.318 的关键里程碑（精选，非逐条流水账），着重梳理近期逐版本变化</p></blockquote><p>官方 <a href="https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a> 已超过 9900 行、覆盖每一个补丁版本。这里只挑对日常使用有实际影响的<strong>里程碑事件</strong>，而不是逐条搬运。想看某个具体版本的完整变更，用会话内的 <code>/release-notes</code> 或直接翻官方文件。</p><p><strong>当前最新版本：v2.1.318</strong>（2026-11-04 发布）。以下按版本梳理近期变化，标记约定：🆕 = 该版本引入的<strong>新特性 / 新命令 / 新配置</strong>；⚠️ = <strong>行为变更</strong>（可能影响你现有的用法）；其余为修复与体验优化。更早的版本只保留速览与主题线索。</p><h2 id="模型发布节点" tabindex="-1">模型发布节点 <a class="header-anchor" href="#模型发布节点" aria-label="Permalink to &quot;模型发布节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>事件</th></tr></thead><tbody><tr><td>1.0.0</td><td>Claude Code 正式 GA，随附 Sonnet 4 与 Opus 4</td></tr><tr><td>2.0.51 附近</td><td>Opus 4.5 发布，推出 Claude Code for Desktop</td></tr><tr><td>2.1.111</td><td>Opus 4.7 上线</td></tr><tr><td>2.1.154</td><td>Opus 4.8 fast mode 大幅降价（2 倍单价换 2.5 倍速度）</td></tr><tr><td>2.1.170</td><td><strong>Fable 5</strong> 发布——Mythos 级模型，能力超过此前任何正式发布的模型</td></tr><tr><td>2.1.197</td><td><strong>Sonnet 5</strong> 发布并成为默认模型，原生 1M token 上下文窗口，发布初期促销价 $2/$10 每 Mtok（2.1.243 起转为正式标价）</td></tr><tr><td>2.1.219</td><td><strong>Opus 5</strong>（<code>claude-opus-5</code>）发布并成为默认 Opus 模型，1M 上下文，fast mode $10/$50 每 Mtok；同版本 Opus 4.7 退出 fast mode</td></tr><tr><td>2.1.251</td><td>按席位计费的 Enterprise 订阅默认模型改为 Opus 5，与其它高端套餐一致</td></tr><tr><td>2.1.257</td><td><strong>Fable 5.1</strong>（<code>claude-fable-5-1</code>）发布并成为默认 Fable 模型：1M 上下文，$10/$50 每 Mtok，缓存读取 $0.25/Mtok</td></tr><tr><td>2.1.277</td><td>Anthropic API 上 Fable 始终出现在 <code>/model</code> 选择器里，只有组织设置禁用它时才显示为灰色</td></tr><tr><td>2.1.280</td><td><strong>Opus 5.5</strong>（<code>claude-opus-5-5</code>）发布并成为默认 Opus 模型：1M 上下文，$4/$20 每 Mtok，缓存读取 $0.20/Mtok，默认推理强度 <code>medium</code>；同版本 Pro 与 Team Standard 套餐的默认模型从 Sonnet 改为 Opus</td></tr><tr><td>2.1.283</td><td>托管设置新增 <code>availableModelsMatch: &quot;exact&quot;</code> 与 <code>deniedModels</code>：新发布的模型版本在列入白名单之前保持封禁，也可以点名封禁某些模型</td></tr><tr><td>2.1.284</td><td><strong>Sonnet 5.5</strong>（<code>claude-sonnet-5-5</code>）发布并成为 Anthropic API 上默认 Sonnet 模型：1M 上下文，$2/$10 每 Mtok（2.1.296 起缓存读取从 $0.20/Mtok 下调至 $0.10/Mtok）</td></tr><tr><td>2.1.293</td><td><strong>Haiku 5.5</strong>（<code>claude-haiku-5-5</code>）发布并成为 Anthropic API 上默认 Haiku 模型：1M 上下文，$0.10/$0.50 每 Mtok（提示词超过 100K 时为 $0.50/$2.50）</td></tr><tr><td>2.1.316</td><td><strong>Opus 4.8 fast mode 弃用</strong>（2026-10-30 起弃用，2026-11-30 移除，移除后直接报错而不再回退标准速度，建议迁至 Opus 5.5）</td></tr></tbody></table><h2 id="协作与编排能力的演进" tabindex="-1">协作与编排能力的演进 <a class="header-anchor" href="#协作与编排能力的演进" aria-label="Permalink to &quot;协作与编排能力的演进&quot;">​</a></h2><p>这条线索大致反映了 Claude Code 从“单会话问答工具”演变为“可编排的并行 agent 平台”的过程：</p><ul><li><strong>自定义 subagent</strong>（约 1.0.60）：可以创建专用 subagent 处理特定任务，<code>/agents</code> 首次上线（交互式管理界面，后在 2.1.198 简化为提示语，改为直接编辑 <code>.claude/agents/</code>)。</li><li><strong>Explore subagent</strong>（2.0.17）：内置一个基于 Haiku 的探索型 subagent，专门用来高效检索代码库、节省主上下文。</li><li><strong>检查点与回滚</strong>（2.0.0）：引入 <code>/rewind</code>，可以撤销代码改动。</li><li><strong>插件体系</strong>（2.0.12 附近）：<code>/plugin install</code>、<code>enable</code>/<code>disable</code>、marketplace 管理陆续完善，支持打包分发技能、subagent、hooks、MCP 服务器。2.1.275 起 claude.ai 账号上启用的技能与插件还会同步到用该账号登录的终端会话。</li><li><strong>技能取代自定义命令</strong>（2.1.0 前后）：<code>context: fork</code> 让技能可以派生到独立 subagent 执行；技能支持热重载，新增/修改后无需重启会话。</li><li><strong>动态工作流</strong>（2.1.154）：让 Claude 把一个大任务编排成跨数十到数百个 subagent 的后台执行方案，<code>/workflows</code> 用于查看进度——这是目前处理“体量远超单会话”任务的核心机制。2.1.271 起工作流撞到用量上限时会暂停，额度重置后自动继续；2.1.281 起提示框下方的后台工作流行会显示名称、进度条、agent 数、已运行时间与总 token 数。</li><li><strong>结构化 Task 工具默认开启</strong>（2.1.142）：<code>TaskCreate</code>/<code>TaskUpdate</code>/<code>TaskGet</code>/<code>TaskList</code> 取代旧版 <code>TodoWrite</code> 成为默认任务追踪方式。⚠️ 后来又收回：2.1.233 起新模型不再提供这组工具，2.1.268 起只在 Claude 3.x、Opus 4.0–4.7、Sonnet 4.0–4.6、Haiku 4.5 上提供（<code>CLAUDE_CODE_ENABLE_TODO_TOOLS=1</code> 可找回）。</li><li><strong>后台 subagent 默认开启</strong>（2.1.198）：subagent 默认在后台运行，Claude 可以一边等待结果一边继续做别的事；同版本 Claude in Chrome 正式 GA。2.1.277 起移除 TaskOutput 工具，Claude 直接用 Read 读取后台任务的输出文件；2.1.281 起「立即发送」（<code>ctrl+enter</code>）不再取消这一轮，而是把正在运行的 shell 命令、subagent 等工作转入后台，队友、<code>/bg</code>、<code>claude agents</code> 派生的会话也沿用父会话的 <code>--setting-sources</code> 限制；2.1.318 起后台 subagent 在所有提供方上都会把运行满 3 分钟的 shell 命令转入后台，避免等待期间 prompt 缓存过期。</li><li><strong>扇出开始设闸</strong>（2.1.212 → 2.1.219）：subagent 派生数、WebSearch 次数、并发 subagent 数、嵌套深度、工作流规模先后被加上默认上限——从“能并行多少就并行多少”转向“默认收着跑、要放开自己调”。其中单会话 200 个的 subagent 派生总数上限在 2.1.224 取消（并发与深度上限仍在）；2.1.271 起「中等」工作流规模的指导值又从 15 个 agent 降到 10 个，Pro 套餐默认「小」规模。</li><li><strong>fork subagent 默认开启</strong>（2.1.232）：<code>subagent_type: &quot;fork&quot;</code> 的 subagent 继承完整对话与 prompt 缓存；交互式会话里非 teammate 的 agent 默认后台运行。2.1.302 起 <code>claude -p</code>、Agent SDK、桌面端与 VS Code 也默认开启 fork subagent（<code>CLAUDE_CODE_FORK_SUBAGENT=0</code> 关闭），桌面端与 VS Code 的主对话 subagent 同样一律后台运行。</li><li><strong>跨会话消息</strong>（2.1.224 → 2.1.239）：<code>SendMessage</code> + <code>ListAgents</code> 让本机或你其它机器上的 Claude Code 会话互相发消息；2.1.232 起在输入框里 <code>@会话名</code> 即可点名，2.1.239 起 Windows 也支持，2.1.283 起全屏模式下来自其它会话的截断消息可以点击展开，2.1.317 起发往正在运行的后台 agent 时，对方正在执行的命令会直接转入后台而不停止，让消息更早送达。</li><li><strong>自托管运行环境</strong>（2.1.224）：<code>claude self-hosted-runner</code> 把你自己的机器或容器变成 Claude Code web / 移动端 / 桌面端会话的运行地（Team 与 Enterprise 套餐）。2.1.281 起运行环境改用私有文件把系统提示词交给 Claude Code，包装脚本里追加的 <code>--system-prompt</code> 要改用 <code>--system-prompt-file</code>。</li><li><strong>subagent 回传加固</strong>（2.1.271 → 2.1.277）：auto mode 下 subagent 改用专门的交还调用向调用方回报，由安全分类器审查（2.1.271）；subagent 的结果放在标明「subagent 输出」的标头下并缩进后才交给主 agent，结果里的文字无法冒充会话自身的指令（2.1.277）。</li><li><strong>Claude Code on the web / Remote Control 生态</strong>持续加固：<code>/teleport</code>、<code>/remote-control</code>、<code>/desktop</code>、<code>claude agents</code> 等命令让本地终端、Web 会话、移动端可以互相流转与监控（集中体现在 2.1.19x 系列的大量修复与体验优化中）。2.1.271 起 Remote 会话（云端与自托管运行环境）也能用 fast mode，2.1.273 起可以从 Claude App 把 Remote Control 会话 fork 成你电脑上的后台会话。</li></ul><h2 id="v2-1-292-→-v2-1-318-逐版本详解" tabindex="-1">v2.1.292 → v2.1.318（逐版本详解） <a class="header-anchor" href="#v2-1-292-→-v2-1-318-逐版本详解" aria-label="Permalink to &quot;v2.1.292 → v2.1.318（逐版本详解）&quot;">​</a></h2><p>这一批版本于 2026 年 10 月中旬至 11 月 4 日发布（CHANGELOG 中无 2.1.297、2.1.298、2.1.313、2.1.315）。以下精选影响日常 CLI、配置或安全行为的变化；桌面、云端及 Slack 专属条目从略。</p><ul><li><strong>v2.1.292</strong> —— 🆕 <code>claude plugin install</code> 新增 <code>--marketplace &lt;source&gt;</code>（按与 <code>marketplace add</code> 相同的策略校验自动添加市场再安装插件）；<code>Agent</code> 工具新增 <code>effort</code> 参数，可按指定推理强度运行 subagent；新增 <code>CLAUDE_CODE_OVERLOADED_RETRY_BASE_DELAY_MS</code> 调整 529 过载重试的基础退避延迟；Claude Mods 新增 <code>prompt.autocomplete</code> 事件、<code>$.model.complete</code> 的 prompt 缓存支持（<code>cache: true</code>）以及 <code>agent.spawn</code> 对 workflow agent 的拦截。⚠️ 本地（stdio）MCP 服务器在所有安装上默认协商 <code>2026-07-28</code> 协议（<code>MCP_PROTOCOL_NEGOTIATION=legacy</code> 退出）；agent 名称及技能/插件文件的 <code>name</code> 最长限制为 256 个字符。安全修复：阻止 PreToolUse hook 与 auto mode 绕过 UNC 网络路径读取确认。</li><li><strong>v2.1.293</strong> —— 🆕 <strong>Claude Haiku 5.5</strong>（<code>claude-haiku-5-5</code>）发布并成为 Anthropic API 默认 Haiku 模型（1M 上下文，$0.10/$0.50 每 Mtok，超 100K 提示词为 $0.50/$2.50）；<code>subagentStatusLine</code> 负载新增 <code>agentType</code>；Mods 的 <code>$.tool.register</code> 新增 <code>isDeferred: false</code> 以直接注入工具 schema。修复用单文件 <code>cat</code>/<code>head</code>/<code>tail</code>/<code>sed -n</code>/<code>grep</code> 查看文件时未触发路径规则与嵌套 <code>CLAUDE.md</code> 加载的问题。</li><li><strong>v2.1.294</strong> —— 修复写成指令句式的 <code>prompt</code> 与 <code>agent</code> hook 放行了本应拦截的操作，并改进 <code>Stop</code> / <code>SubagentStop</code> 上指令式 <code>prompt</code> hook 的判定以减少过早停止。</li><li><strong>v2.1.295</strong> —— 🆕 <code>command</code> 与 <code>http</code> hook 新增 <code>onFailure: &quot;block&quot;</code>（无法启动、超时或异常退出码时阻断操作而非放行）；支持终端进度状态协议（OSC 7501）；<code>/copy</code> 选择器新增引用文本项（复制草稿时去掉 <code>&gt;</code> 前缀）；用户设置支持 <code>forceLoginMethod: &quot;gateway&quot;</code> 与 <code>forceLoginGatewayUrl</code>；新增 <code>CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS</code> 限制无人值守模式下等待 429/529 的最长时间；Mods 新增 <code>$.ui.notify</code>。⚠️ tool search 按需加载的 MCP 工具描述上限从 2,048 提高到 16,384 字符；subagent 从 <code>skills</code> 字段预加载最多 32 个技能；在已 attach 的后台会话空闲提示符下按两次 Ctrl+C 只 detach 并保留待触发的 <code>/loop</code>（按 Esc 才停止循环）。</li><li><strong>v2.1.296</strong> —— 🆕 subagent frontmatter 与 <code>--agents</code> 定义新增 <code>autoCompactWindow</code>，可早于主会话触发自动压缩；新增 <code>CLAUDE_CODE_WORKFLOW_SUBAGENT_MODEL</code> 单独指定所有 workflow agent 的模型；新增 <code>CLAUDE_CODE_OVERLOADED_RETRY_MAX_DELAY_MS</code> 调整 529 重试的最大退避延迟；<code>Read</code> 工具新增 <code>allow_large</code> 参数以单次读取超大文本文件；<code>/plugin</code> 对因同名插件已启用而被跳过 hook 的插件显示提示。⚠️ Sonnet 5.5 缓存读取计费下调至 $0.10/Mtok；预发送的 MCP 工具描述与服务器说明默认上限从 2,048 提高到 4,096 字符；按 <code>←</code> 将会话转入后台时，正在启动的一轮或 <code>!</code> 命令会被停止而非在后台暗中跑完。</li><li><strong>v2.1.299</strong> —— 🆕 终端新增<strong>空闲自动压缩</strong>（Idle compaction）：超过 200K token 的对话闲置约 54 分钟后，会在 1 小时 prompt 缓存过期前自动压缩，可用 <code>settings.json</code> 的 <code>&quot;idleCompaction&quot;: false</code> 关闭或用 <code>CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS</code> 调整阈值；新增 <code>CLAUDE_CODE_DISABLE_FILE_MENTIONS=1</code> 让 <code>@</code> 文件引用只传路径而不内联文件内容；<code>claude agents</code> 视图支持 <code>/effort</code> 与 <code>/fast</code>；<code>claude plugin eval</code> 新增 <code>--disallow-tools</code>（及用例字段 <code>disallowed_tools</code>）；网关环境支持 <code>CLAUDE_CODE_ATTRIBUTION_HEADER=0</code> 移除归属块；<code>/usage</code> 新增针对 <code>max</code> 强度、工作流、常驻上下文与大工具结果的告警；Mods 新增 <code>$.prompt.media</code> 与 <code>$.session.identity()</code>。⚠️ <code>UserPromptSubmit</code> hook 改在技能或自定义斜杠命令展开前运行，阻断提示词即可一并阻止内嵌的 <code>!</code> 命令；技能自身 frontmatter 里的 <code>UserPromptSubmit</code> hook 从调用该技能之后的下一条提示词才开始生效；MCP allow 规则与 agent <code>tools:</code> 列表改为严格匹配完整规范化服务器名（<code>mcp__&lt;server&gt;__*</code>）；文件名含隐藏/双向控制字符或 <code>&lt;&gt;</code> 的技能与命令不再加载。</li><li><strong>v2.1.300</strong> —— 🆕 Claude Platform on AWS 支持 <code>/advisor</code>，新增 <code>CLAUDE_CODE_DISABLE_ADVISOR_TOOL=1</code> 关闭顾问工具；OTel <code>api_request</code> 事件拆分 <code>cache_creation_5m_tokens</code> 与 <code>cache_creation_1h_tokens</code>，trace span 补齐 GenAI 语义约定属性；Mods 新增输入框 <code>virtualText</code> 装饰、<code>$.ui.view({ agentId })</code>、<code>prompt.change</code> 事件，以及在 <code>agent.spawn</code> 中改写 workflow agent 的 <code>prompt</code> 与 <code>model</code>。⚠️ 移除 <code>claude remote-control</code> 上原本无效的 <code>--sandbox</code> 与 <code>--no-sandbox</code> 标志（现传参直接报错，改用 <code>sandbox.enabled</code> 设置）；<code>PreToolUse</code> 与 <code>PermissionRequest</code> hook 返回的 <code>updatedInput</code> 会按工具 schema 校验（剔除未知键，参数不合法则拒绝调用）；发往 <code>api.anthropic.com</code> 的大请求即使关闭遥测也默认启用 gzip 压缩（<code>CLAUDE_CODE_GZIP_REQUEST_BODIES=0</code> 关闭）。</li><li><strong>v2.1.301</strong> —— 🆕 新增 <code>CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS</code>，在额度重置时间过远时直接结束请求而非干等；vim 模式新增 <code>%</code> 括号匹配跳转（可配合 <code>d</code>/<code>c</code>/<code>y</code>）；OTel <code>tool_decision</code> 事件新增 <code>classifier_verdict</code>、<code>permission_mode</code> 与 <code>classifier_category</code>；Mods 的 <code>Input</code> 组件支持多行 <code>rows</code>。⚠️ 技能与命令最多只填充前 64 个参数名（每个最长 64 字符）。改进切换小窗口模型时的自动压缩（先由原模型总结再切换）。</li><li><strong>v2.1.302</strong> —— 🆕 新增 <code>CLAUDE_CODE_AUTO_MODE_MODEL</code> 指定客户端本地 auto mode 分类器使用的模型；<code>/config</code> 新增 <code>Idle compaction</code> 开关行。⚠️ <strong>fork subagent（<code>subagent_type: &quot;fork&quot;</code>）在 <code>claude -p</code>、Agent SDK、桌面端与 VS Code 中也改为默认开启</strong>（与终端一致，<code>CLAUDE_CODE_FORK_SUBAGENT=0</code> 关闭，<code>claude mcp serve</code> 不提供）；桌面端与 VS Code 的主对话 subagent 一律后台运行，而 subagent 自己在 <code>-p</code>、SDK、桌面端与 VS Code 中派生的 Agent 调用默认前台运行；未指定权限模式的 <code>claude -p</code> 与 Agent SDK 会话在第三方提供方、关闭遥测或全新安装下统一从 <code>default</code> 模式起步；同一事件的 <code>prompt</code> 与 <code>agent</code> hook 最多同时运行 12 个；<code>/design-sync</code> 与 <code>/design-login</code> 提示独立版 Claude Design（<code>claude.ai/design</code>）将于 2026-12-14 下线；<code>Read</code> 工具拒绝超过 128 MB 的图片源。</li><li><strong>v2.1.303 / v2.1.306 / v2.1.308</strong> —— 稳定性与可靠性修复（包括云端会话内无环境变量运行 <code>claude -p</code> 误报未登录、多 MCP 工具会话把 API 错误误报为上下文超长等）。</li><li><strong>v2.1.304</strong> —— 🆕 新增 <code>/auto-mode-setup</code> 引导式配置，读取项目与近期会话来帮助 auto mode 适应当前环境（Bedrock、Vertex、Foundry、网关与关闭遥测会话均可用）；新增 <code>/claude-api managed-agents-secure</code> 安全配置比对；Pro 与 Max 套餐恢复长时间闲置会话、且会显著消耗 5 小时额度时给出提示；Mods 的 <code>tool.check</code> 支持 <code>decider: &quot;person&quot;</code>（强制人工审批）与 <code>e.isReadOnly</code>，<code>settings.read</code> 可按层级改写合并后的设置。⚠️ <code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code> 支持 <code>k</code>/<code>M</code> 后缀（如 <code>200k</code>）；自定义 <code>ANTHROPIC_BASE_URL</code> 网关后默认开启 tool search（网关返回 400/422 时自动回退）；压缩完成后会自动把技能列表重发给 Claude，而 <code>/reload-skills</code> 只补发新增或变更的技能；单一来源的技能每会话最多注册 1,024 个 hook 与 16,384 字符 matcher。</li><li><strong>v2.1.305</strong> —— 🆕 Linux 沙箱新增 <code>sandbox.allowNestedUserNamespaces</code>（允许 Chromium、rootless podman 等创建用户命名空间，注意这会让它们绕过沙箱的文件保护）；新增 <code>CLAUDE_CODE_RETRY_WATCHDOG_USAGE_LIMIT_RECHECK_MS</code> 定期重查提前解除的用量上限；<code>/usage</code> 与 <code>/doctor</code> 的每条告警附带单行修复说明，按 <code>f</code> 一键应用。⚠️ <code>allowedMcpServers</code> 不再过滤 <code>managed-mcp.json</code> 里仅在 <code>env</code> 中使用 <code>${VAR}</code> 的 stdio 服务器，需禁用请改用 <code>deniedMcpServers</code>。</li><li><strong>v2.1.307</strong> —— 🆕 新增 <code>/claude-api api-version</code>，可将 Claude API 代码迁移至 <code>2026-10-21</code> 版本；新增 <code>claude_code.safety_event</code> OTel 事件（后在 2.1.312 停发）。⚠️ <code>axScreenReader</code> 设置与 settings <code>env</code> 里的 <code>CLAUDE_AX_SCREEN_READER</code> 只在用户级、托管设置或 <code>--settings</code> 中生效；自托管运行环境的 checkout hook 默认 30 分钟超时（可用 <code>--checkout-hook-timeout-min</code> 调高或设 <code>0</code>）。</li><li><strong>v2.1.309</strong> —— ⚠️ <code>claude ultrareview</code>（及 2.1.314 起的 <code>/ultrareview</code>）在运行 git 前要求先通过工作区信任确认，脚本可传无值标志 <code>--trust-workspace</code> 或设 <code>CLAUDE_CODE_DISABLE_ULTRAREVIEW_TRUST_CHECK=1</code>；<code>sed -i</code> 改走标准 Bash 提示并按原样执行，不再生成模拟文件编辑预览，也不再由 <code>/rewind</code> 恢复；子目录下超大的嵌套 <code>CLAUDE.md</code> 只加载开头部分，避免反复触发自动压缩。修复 macOS/Linux 沙箱命令在沙箱外执行 shell 启动文件、符号链接绕过 <code>denyWrite</code> 以及 <code>--add-dir</code> 同名技能无法访问（现以 <code>&lt;folder&gt;:&lt;name&gt;</code> 提供）等问题。</li><li><strong>v2.1.310</strong> —— 🆕 <code>Monitor</code> 工具与插件监视器扩展到 Bedrock、Vertex、Foundry 以及关闭遥测或非必要流量的环境（长耗时前台 <code>sleep</code> 同样在那里被拦截）；Linux 下 <code>/sandbox</code> 与启动告警会点名 Ubuntu AppArmor 对用户命名空间的限制并给出解除方法。</li><li><strong>v2.1.311</strong> —— 🆕 <code>claude self-hosted-runner</code> 新增 <code>--hold-idle-file</code> 与 <code>--max-hold-min</code>，在宿主机报告仍有遗留进程时保持空闲会话。⚠️ 交互式终端里的 <code>ultrathink</code> 在 Opus 5.5、Sonnet 5.5、Haiku 5.5 与 Fable 5.1（Anthropic API）上将该轮推理强度提至 <code>xhigh</code>；模型名称与 ID 在 <code>[1m]</code> 后缀无实际作用的模型上去掉该后缀与标签（传入仍兼容）；<code>settings.json</code> 与 Mod <code>$.env.set</code> 里的 <code>DISABLE_COMPACT</code> 只能关闭压缩、不能重新开启；Bedrock、Mantle、Vertex 与 Foundry 默认从 <code>downloads.claude.ai</code> 加载签名模型目录（<code>CLAUDE_CODE_MODEL_CATALOG=off</code> 关闭）；<code>claude purge</code> 明确说明只删除本机数据。</li><li><strong>v2.1.312</strong> —— 🆕 全屏模式下点击排队消息下方的「to send now」提示即可立即发送；网关新增 <code>oidc.user_id_claim</code>。⚠️ Bedrock、Vertex、Foundry 与 Mantle 对未识别的模型名（如自定义部署名、推理配置 ARN）默认使用精简系统提示词（<code>CLAUDE_CODE_SIMPLE_SYSTEM_PROMPT=0</code> 保留完整提示词），安全拦截后的自动模型切换也覆盖这类未识别模型名（<code>CLAUDE_CODE_DISABLE_REFUSAL_FALLBACK=1</code> 关闭）；单会话内（含 subagent）同时运行的 <code>prompt</code> 与 <code>agent</code> hook 上限设为 24 个；subagent 的 <code>autoCompactWindow</code> 可压低 <code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code> 设定的窗口；用量提示里的「session limit」统一改称「5-hour limit」。</li><li><strong>v2.1.314</strong> —— 🆕 新增 <code>permissions.blockWritesOutsideWorkingDirectories</code>，在所有权限模式下禁止 <code>Write</code>、<code>Edit</code>、<code>NotebookEdit</code> 写入工作目录以外的路径；VS Code 与 Claude Desktop Code 标签页支持空闲自动压缩（Idle compaction），关闭遥测的订阅会话以及开启 1 小时缓存的 Bedrock / Vertex / Foundry / 网关会话同样支持；网关上游支持按 IdP 组路由的 <code>groups</code> 列表与 Bedrock <code>guardrail_trace</code>。⚠️ hook 的 <code>if:</code> 条件支持用 <code>Monitor(tail *)</code> 匹配 Monitor 工具的 shell 命令（与 <code>Bash(tail *)</code> 相同）；<code>/permissions</code> 的审查标签页改名为 <code>Recently blocked</code>，且在终端过矮无法完整显示命令时拒绝批准；<code>FORCE_HYPERLINK=false</code>（及 <code>no</code>/<code>off</code>）改为关闭超链接；<code>PreCompact</code> hook 输出截断在 10,000 字符，且 <code>~/.claude/skills/.trash</code> 与 <code>~/.claude/plugins/.trash</code> 各自保留约 1,024 条目上限。</li><li><strong>v2.1.316</strong> —— 🆕 新增 <code>CLAUDE_CODE_DISABLE_ULTRATHINK=1</code> 关闭 <code>ultrathink</code> 关键词；新增 <code>CLAUDE_CODE_SUBAGENT_EFFORT</code> 为未显式指定强度的 subagent 设置默认推理强度（不再继承主会话）；新增 <code>CLAUDE_CODE_DISABLE_LOOPED_CROSS_CERT_DROP</code> 保留互相交叉签名的系统证书；网关支持团队共享月度预算 <code>pooled_budget</code>、多层合并策略 <code>managed.policy_mode: layered</code> 与 Bedrock <code>guardrail.input_tagging</code>。⚠️ <strong>Opus 4.8 的 fast mode 自 2026-10-30 起弃用，将于 2026-11-30 移除</strong>（移除后请求直接报错且不回退标准速度，请迁至 Opus 5.5）；Team 与 Enterprise 登录从 Anthropic API 拉取的服务端托管设置无需审批直接生效，且未通过校验的本地缓存副本会被拒绝。</li><li><strong>v2.1.317</strong> —— 🆕 Agent SDK 的 hook 回调支持 <code>onFailure: &quot;block&quot;</code>；自托管运行环境新增 <code>CLAUDE_CODE_DISABLE_NESTED_SESSION_ID=1</code>（让会话内运行的 <code>claude -p</code> 沿用外层会话 ID 与 transcript，默认改为独立 ID 以免串台）；网页或 shell 工具调用向网络发送当前账号邮箱前会先询问确认；OTel 指标、事件与 span 新增 <code>anthropic.plan</code>、<code>anthropic.seat_type</code>、<code>anthropic.provider</code> 与 <code>anthropic.custom_base_url</code>；网关管理 API 新增 <code>GET /v1/organizations/analytics/cost</code> 费用报表。⚠️ <code>SendMessage</code> 发给正在运行的后台 agent 时，对方正在执行的命令会直接转入后台而不停止，使消息更早送达；使用不同于主对话模型的 subagent 与队友改为采用该模型自己保存的推理强度或默认强度，不再继承主会话强度；移除 <code>Read</code> 工具「文件自上次读取后未变化」的占位短句，再次读取未改动文件会照常返回内容；退出时对插件监视器不再弹出「后台工作正在运行」确认。</li><li><strong>v2.1.318</strong> —— 🆕 <code>claude auth status</code> 新增 <code>loginExpiresAt</code>、<code>claude -p</code> 的 JSON 结果新增 <code>credential_expires_at</code>（显示已保存的 claude.ai 登录何时到期），且到期前 10 天起 <code>claude -p</code> 文本模式会在 stderr 打一行预警；Mods 的 <code>$.model.fork</code> 新增 <code>effort</code> 选项，并在会话询问是否启用 Claude 编写的 Mod 时记录你的回答；网关 <code>mantle</code> 上游支持 <code>assume_role</code>，自托管运行环境 orchestrator 的 spawn-runner hook 新增 <code>CLAUDE_RUNNER_SPAWN_REASON</code>。⚠️ 在 IDE 终端内启动 Claude Code 时不再自动安装或更新 IDE 扩展（改在外部终端运行 <code>/ide</code> 或从编辑器扩展面板管理）；后台 subagent 在所有提供方上都会把运行满 3 分钟的 shell 命令转入后台，防止等待期间 prompt 缓存过期；「消息被标记时切换模型」设为「每次询问」时，subagent 遇到标记会直接停止而非切换模型；<code>deniedMcpServers</code> 的 URL 条目也会拦截上游 URL 匹配的 Anthropic 官方服务器，以及云端与自托管运行环境里注入了自身 URL 的 connector；<code>/claude-api managed-agents-onboard</code> 默认给新建 agent 的内置工具与模板 MCP 工具设置 <code>auto</code> 权限策略。</li></ul><h2 id="v2-1-284-→-v2-1-291-逐版本详解" tabindex="-1">v2.1.284 → v2.1.291（逐版本详解） <a class="header-anchor" href="#v2-1-284-→-v2-1-291-逐版本详解" aria-label="Permalink to &quot;v2.1.284 → v2.1.291（逐版本详解）&quot;">​</a></h2><p>这一批版本于 2026 年 9 月 28 日至 10 月 6 日发布。以下精选影响日常 CLI、配置或安全行为的变化；桌面、云端及 Slack 专属条目从略。</p><ul><li><strong>v2.1.284</strong> —— 🆕 Sonnet 5.5 成为 Anthropic API 默认 Sonnet；auto mode 在读取工作目录以外文件的提示中新增「这次允许、下次仍询问」选项；交互终端增加 <code>/mcp reconnect all</code>，可一次重试所有掉线或待认证的 MCP 服务器。Ultracode 改为独立开关，不再强制 <code>xhigh</code> 推理强度，见<a href="/Front2Full/manual/agent/claude-code/commands-model-permissions">模型与推理</a>。</li><li><strong>v2.1.285</strong> —— 🆕 <code>CLAUDE_CODE_DISABLE_WEB_FETCH=1</code> 可关闭 WebFetch；<code>claude --desktop</code> 可在当前目录打开 Claude 桌面应用，也可结合 <code>--continue</code> / <code>--resume</code> 打开会话；新增 <code>claude plugin configure &lt;plugin&gt;</code>；托管设置可用 <code>allowedProviders</code> 限制机器允许的模型提供方。</li><li><strong>v2.1.286</strong> —— 权限提示堆叠时显示当前请求序号；修复会话恢复时丢失并行工具调用后的对话，以及无效模型导致请求失败的问题；fallback 模型不能运行 fast mode 时自动退回标准速度。</li><li><strong>v2.1.287</strong> —— 🆕 插件可注册 Claude Mods 以扩展更深层行为；加入内置侧边审查插件 <code>cc-plugin-you-should-know</code>，在支持的第一方会话中可用 <code>/plugin enable cc-plugin-you-should-know@builtin</code> 开启；MCP 支持新协议的 URL elicitation。</li><li><strong>v2.1.288</strong> —— 🆕 <code>/code-review</code> 增加 <code>--max-findings &lt;n&gt;|all</code>，可调整报告数量并记住选择，输入 <code>--max-findings default</code> 恢复默认；清空输入框后按 <code>↑</code> 可找回 Ctrl+C 清除的草稿（含粘贴文本和图片）。修复响应中断、长对话自动压缩及 <code>--resume</code> 丢失内容等问题。</li><li><strong>v2.1.289</strong> —— 加固 Bash 与 Read deny/ask 规则，修复沙箱自动放行时复合 shell 命令、环境变量前缀或符号链接绕过规则的问题。</li><li><strong>v2.1.290</strong> —— 插件 hook 新增 agent 身份与组织审批边界信息；新增 <code>claude attach &lt;会话名片段&gt;</code>、<code>claude logs &lt;会话名片段&gt;</code>，便于按名称连接与查看会话；<code>/status</code> 与 <code>claude doctor</code> 会提示托管设置覆盖本机沙箱路径或域名规则的情况。</li><li><strong>v2.1.291</strong> —— 修复 v2.1.290 中云端会话可能丢弃权限提示答复的问题，以及 v2.1.288 中退出时可能丢失会话末尾消息的问题。</li></ul><p>完整发布记录见 <a href="https://github.com/anthropics/claude-code/releases" target="_blank" rel="noreferrer">Anthropic Claude Code Releases</a>。</p><h2 id="v2-1-278-→-v2-1-283-逐版本详解" tabindex="-1">v2.1.278 → v2.1.283（逐版本详解） <a class="header-anchor" href="#v2-1-278-→-v2-1-283-逐版本详解" aria-label="Permalink to &quot;v2.1.278 → v2.1.283（逐版本详解）&quot;">​</a></h2><p>这是手册上一版（截至 v2.1.277）之后的全部版本，共 5 个发布（CHANGELOG 与 npm 上都没有 2.1.279），于 2026 年 9 月 19 日至 25 日陆续推出。VS Code 扩展、Claude Code on the web（2.1.282 起的条目改标为 Cloud sessions）、Claude Tag（Slack）、Code Review 等非 CLI 条目从略。🆕 新特性、⚠️ 行为变更单独标出，其余为修复/优化的精选。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>这一批版本里有几条<strong>最容易让旧配置悄悄失效</strong>：没有配置权限模式的交互式会话在所有套餐与提供方上都以 auto mode 起步（283）；项目级与本机 settings 的 <code>env</code> 里开启 OpenTelemetry 导出、设置端点或采集内容的变量一律被忽略（282）；<code>anthropic-skills:</code> 命名空间下的技能、命令与工作流命令不再加载（282）；自托管运行环境改用文件传系统提示词，包装脚本或 <code>command</code> hook 里追加的 <code>--system-prompt</code> 要改成 <code>--system-prompt-file</code>（281）；写了 <code>&quot;attribution&quot;: false</code> 的 settings 文件会被旧版本整份跳过（281）；<code>y</code> / <code>n</code> 不再默认确认或关闭对话框（280）；<code>PermissionRequest</code> 事件上的 agent 型 hook 不再运行（280）；用户级 settings 里旧的顶层 <code>effortLevel</code> 不再作用于 Opus 5.5 这类新模型，Pro 与 Team Standard 的默认模型改为 Opus（280）。</p></div><p><strong>v2.1.283</strong>（上一版手册基准）</p><ul><li>⚠️ <strong>交互式会话默认以 auto mode 起步的范围扩大</strong>：没有配置权限模式时，第三方提供方与关闭遥测的交互式会话也以 auto mode 起步（此前只有 Pro、Max、Team 套餐如此；按官方文档，现在终端与 VS Code 里的交互式会话在所有套餐与提供方上都是这样，<code>-p</code> 与 Agent SDK 仍从 <code>default</code> 起步），<code>permissions.defaultMode</code> 照样优先。</li><li>🆕 <strong>按版本管控可用模型</strong>（托管设置）：<code>availableModelsMatch: &quot;exact&quot;</code> 让 <code>availableModels</code> 里的每个模型 ID 只放行它点名的那个版本（<code>&quot;claude-opus-5&quot;</code> 不再顺带放行 Opus 5.5），新版本在列入名单之前一直被挡住；<code>deniedModels</code> 点名封禁某些模型，即使 <code>availableModels</code> 允许也不行。</li><li>🆕 <strong><code>/doctor prompt-audit</code></strong>（也可以写 <code>/checkup prompt-audit</code>）：审查你的 CLAUDE.md、技能、agent 与命令里为旧模型写的提示词套路；过时的路径、过时的命令与相互矛盾的说明文件排在报告最前，Claude Code 文档里写明的思考关键词会保留，不被当成过时写法。</li><li>🆕 给 LLM 网关的提示请求头新增 <code>x-claude-code-prompt-id</code>（同样要设 <code>CLAUDE_CODE_GATEWAY_HINT_HEADERS=1</code>），网关可以据此把服务同一条用户提示词的请求归到一起；<code>OTEL_LOG_TOOL_CONTENT=1</code> 时，MCP 工具、WebFetch 与 WebSearch 的输出也写进 <code>tool.output</code> span 事件。</li><li>🆕 Claude apps 网关：配置里可选的 <code>load_test_mode</code> 块让请求照常构建、签名但不发往上游，客户端收到固定回复，用来给部署做压测；新增对接 Amazon Bedrock Mantle 端点的 <code>mantle</code> 上游提供方。</li><li>🆕 全屏模式下，来自你其它会话的截断消息可以点击展开；stream-json 的 <code>system/init</code> 消息里，<code>plugin_errors</code> 中 <code>--plugin-dir</code> 加载失败的条目带上 <code>path</code>，点明没加载上的目录。</li><li>⚠️ <strong><code>--system-prompt</code> 与 <code>--append-system-prompt</code> 可以和各自的 <code>-file</code> 形式同时使用</strong>，文件里的文本排在前面。</li><li>⚠️ 撤回 2.1.282 对 <code>claude-ai</code> 名字的保留：以它命名的技能、命令、工作流以及 MCP 服务器的技能与 prompt 重新加载，<code>Skill(claude-ai:*)</code> 规则恢复为普通的前缀规则。<code>Skill(anthropic-skills:&lt;name&gt;)</code> 的 deny 规则在 Claude Desktop 以插件形式下发该技能时也能拦住它，<code>Skill(skill:&lt;name&gt;)</code> 的 deny 规则同时匹配技能的别名与显示名。</li><li>⚠️ <code>claude plugin eval</code> 在装有 git 时要求 git 2.31 或更高版本，版本太旧会被拒绝并给出版本号；<code>/model</code> 选择器的 Opus 一行与 Default 模型名在 Opus 本就是 1M 窗口时去掉「(1M context)」字样（窗口大小不变）；连续 20 条提示词建议都没被采用后，终端里的建议出现得更少，采用一条即恢复。</li><li>⚠️ <code>/rewind</code> 与 <code>/diff</code> 的列表改用与其它列表相同的 <code>select:*</code> 按键动作（原来的 <code>messageSelector:*</code> / <code>diff:*</code> 重绑定仍然有效）；<code>/workflows</code> 运行列表按其它列表的规则定高（内联时占半个终端）；自动布设（不是你要求）的 artifact 监视在 3.5 小时无活动后结束，再次发布或监视即重新布设；<code>/ultrareview</code> 的启动对话框会说明，评审本地分支可能上传已跟踪文件里未提交的改动。</li><li>⚠️ 自托管运行环境：生命周期 hook 里的 git 跳过仓库自带的 Git LFS <code>pre-push</code> hook、忽略可写的系统级 <code>core.hooksPath</code>，没有 <code>--configure-git</code> 时不签名提交；由 Anthropic 管理 git 时，运行环境自己的 git 始终校验 Anthropic 的 git 路由，并在告警里说明 <code>GIT_SSL_CAINFO</code>、<code>GIT_SSL_NO_VERIFY</code> 分别对哪里生效。</li><li>安全：修复 Windows 上 PowerShell 工具允许用 <code>cmd /c rd</code>、<code>rmdir</code>、<code>del</code>、<code>erase</code> 删除驱动器根目录、主目录等 <code>Remove-Item</code> 会拒绝删除的目录（官方文档另列了关闭这项检查的 <code>CLAUDE_CODE_DISABLE_POWERSHELL_CMD_RM_DENY</code>）；修复托管的 <code>sandbox</code> 设置里只要有一个嵌套值不合法就整块被忽略（现在非法值按最严处理，其余照常生效）。</li><li>MCP：长时间运行的工具调用转入后台后不再丢弃进度通知（后台任务显示最新进度）；会话结束时仍在启动的 stdio 服务器不再被留着运行；无状态远程服务器短暂返回 HTTP 404（如代理正在重新部署）后，不再整场会话不可用却仍显示为已连接；没有合法 URL 的服务器登录时不再报出看不懂的 SDK 错误，<code>/mcp</code> 也不再为它提供 Authenticate；<code>claude mcp add</code>、<code>add-json</code>、<code>remove</code> 写不进用户或本机配置文件（如在沙箱里）时不再报告成功。</li><li>MCP 改进：MCP 工具返回的图片同时存成文件，Bash、Read 等工具可以直接打开；<code>/mcp</code> 工具列表一次显示更多工具，能用翻页键与鼠标滚动，组织封禁的工具带告警图标；<code>/context</code> 把 MCP 服务器说明单列一行并计入总量。</li><li>插件：<code>claude plugin validate</code> 对 Claude Code 实际装不上的插件或 marketplace 名字报错，也不再放过 <code>outputStyles</code>、<code>themes</code>、<code>monitors</code>、<code>lspServers</code> 路径缺失或指向插件目录之外的插件；修复 <code>claude plugin uninstall</code> 可能误删 id 只差大小写的另一个插件（连同其选项与密钥）；修复没声明版本的插件缓存丢失时被静默恢复成源的最新提交，而不是已安装的那一版；修复主目录或配置目录搬家后（如 bind mount 的 devcontainer）插件与 marketplace 以「cache-miss」加载失败。</li><li><code>installed_plugins.json</code>：存有非法插件 id 的记录时不再显示为空；存有本版本读不懂的记录时不再被改写而丢记录，<code>claude plugin</code> 命令会点出那条记录并说明恢复办法；整个文件读不了时，先把内容另存到旁边的文件再重建，<code>claude plugin list</code> 会指出这个文件。此外 <code>claude plugin details</code> 能数出在 <code>plugin.json</code> 里声明的 MCP 服务器，<code>claude plugin marketplace remove</code> 会列出随 marketplace 一并卸载的插件。</li><li>修复模型回退期间启动的动态工作流让每个 agent 都跑在回退模型上，而不是重试配置的模型；修复 Haiku 作为会话主模型时 <code>DISABLE_PROMPT_CACHING_HAIKU</code> 不起作用；修复 <code>ANTHROPIC_DEFAULT_HAIKU_MODEL</code> 钉住别的模型时 <code>/model</code> 仍显示写死的 Haiku 版本与价格；修复关闭遥测时 <code>/usage</code> 看不到 Fable 的每周额度。</li><li>修复关闭遥测（<code>DISABLE_TELEMETRY</code> 或 <code>DO_NOT_TRACK</code>）时付费套餐用不了 Remote Control；修复从 git 仓库的子目录启动时，Claude 改写自己的自动记忆笔记被当成敏感文件写入拦下；修复沙箱里的 <code>git</code> 让凭证 helper 保存沙箱代理的登录信息（打印「failed to store」）；修复 CA 证书以 <code>GIT_CONFIG_COUNT</code> 环境变量对传给 git 时，worktree 检出（如 Git LFS 下载）证书校验失败。</li><li>按键与 vim：<code>keybindings.json</code> 里拼错的修饰键（如 <code>ctl+k</code>）不再被静默接受，改在调试日志里告警并提示正确写法；快速连续到达的按键（预输入、按键重复、ssh 或 tmux 下的突发输入）不再按过时的状态处理；内置的快捷键指南改正为组合键 3 秒（不是 1 秒）超时、<code>cmd</code> 并非 <code>meta</code> 的别名；vim 模式修正 <code>.</code> 重复、<code>J</code> 合并行的空格与光标位置等一批与 Vim 不一致的行为。</li><li>界面：<code>/tasks</code> 每行带状态图标、名称与完整信息，任务多时标题与按键提示留在屏幕上，并支持翻页键、滚轮与点击；<code>/help</code>、<code>/hooks</code>、<code>/copy</code>、<code>/chrome</code>、<code>/memory</code>、<code>/ide</code>、<code>/release-notes</code>、<code>/rewind</code>、<code>/diff</code>、<code>/remote-env</code>、<code>/plugin</code> 等选择列表同样支持翻页键、滚轮与点击；压缩时的 spinner 从压缩开始时计时、实时统计摘要的 token 数，取代百分比进度条；Warp 终端里的 markdown 链接可以点击；屏幕阅读器模式下，权限对话框不再把引号里的命令与路径当成对话框自己的文字朗读。</li><li>更快的首轮：首个请求复用预先建立的 API 连接；首条回复末尾的一个模式编译步骤改在回复流式输出期间完成；<code>claude -p</code> 与 Claude Code Remote 不再加载交互式 UI，auto mode 分类器规则与 Artifact 工具改为首次使用时才加载；claude.ai 账号首次运行、Artifact 工具的功能还不确定时，输入框不再为检查它们最多等 1.5 秒。</li><li>修复 SDK 会话在一轮提前结束时丢掉延迟的工具调用或已完成的工具结果、worker 重启后保留的审批提示，以及非流式回退的 <code>result.usage</code>；技能所属插件加载失败时，Skill 工具如实告诉 Claude 是插件没能加载，而不是说技能没装。</li></ul><p><strong>v2.1.282</strong></p><ul><li>🆕 <strong><code>maxProseWidth</code> 设置</strong>：在宽终端里限制 Claude 正文的行宽，段落、标题、列表与引用在这个列数内换行，表格与代码块仍用满终端宽度（官方文档：取不小于 40 的整数）。</li><li>🆕 <strong>托管设置 <code>allowClaudeInChromeWithManagedMcp</code></strong>：让 <code>claude --chrome</code> 能与独占 MCP 控制的 <code>managed-mcp.json</code> 同时使用，Chrome 被拦下时的报错也会点出这个设置。</li><li>🆕 Claude apps 网关新增 <code>store.readiness_grace_seconds</code>，Postgres 短暂中断（如数据库故障切换）期间 <code>/readyz</code> 仍保持就绪；全屏模式下 <code>/feedback</code> 的草稿列表多了滚动条（鼠标悬停时出现）。</li><li>⚠️ <strong>项目级与本机 settings 忽略会开启 OpenTelemetry 导出、设置导出端点或采集内容的变量</strong>（如 <code>CLAUDE_CODE_ENABLE_TELEMETRY</code>、<code>OTEL_LOG_*</code>），这些要写在 shell、用户级或托管设置里；启动时会有提示，<code>/status</code> 与 <code>claude doctor</code> 也会列出项目设置里被忽略、或把遥测关掉的遥测变量。</li><li>⚠️ <strong>保留 <code>anthropic-skills</code> 与 <code>claude-ai</code> 两个命名空间</strong>：落在其中的技能文件夹、命令文件与工作流命令不再加载（同名插件仍会加载，但与同步来的技能重名时让位）；以这两个名字配置的 MCP 服务器不再列出技能与 prompt（工具照常可用，改掉服务器名即可恢复）；<code>Skill(anthropic-skills:*)</code> 与 <code>Skill(claude-ai:*)</code> 的 allow 规则只覆盖从 claude.ai 同步来的技能，不再覆盖只是用了这类名字的插件或其它技能。对 <code>claude-ai</code> 的保留在 2.1.283 撤回。</li><li>⚠️ 直连 Anthropic API 且关闭遥测时，auto mode 也默认使用服务端分类器（<code>CLAUDE_CODE_AUTO_MODE_SERVER=0</code> 退出）；托管设置或 <code>--settings</code> 设了 <code>allowUnsandboxedCommands: false</code>，或托管设置设了 <code>allowManagedDomainsOnly: true</code> 时，项目级与本机设置里的 <code>sandbox.excludedCommands</code> 条目被忽略。</li><li>⚠️ Windows 与 WSL：管理员策略（HKLM 或 <code>managed-settings.json</code>）存在但无效或读不了时，用户可写的 HKCU 与 WSL 的 <code>/etc/claude-code</code> 也不再生效。中间带 <code>:*</code> 的 Bash 权限规则此前在 settings 文件里被跳过、只有 <code>--allowedTools</code> 认，现在对所有来源都生效，启动时会告警说明它怎么匹配。</li><li>安全：托管设置里 <code>disableClaudeAiConnectors</code>、<code>allowManagedPermissionRulesOnly</code> 这类布尔锁定键的值写错时不再被忽略（锁定照样生效，启动时点名这个键）；托管的 <code>permissions</code>、<code>autoMode</code>、<code>worktree</code>、<code>attribution</code> 里有一个嵌套值不合法时不再整块作废；托管 <code>allowManagedPermissionRulesOnly</code> 生效时，仓库、用户与 <code>--add-dir</code> 的技能、命令以及 skills-dir 插件清单不能再用 <code>allowed-tools</code> 预先批准自己的工具；启动时不再经由仓库里的符号链接（通过 <code>..</code> 或 <code>/.vol</code> 形式的内核路径到达 macOS 的 <code>/Network</code>）读取 CLAUDE.md 与规则文件。</li><li>修复历史里有 API 无法解密的网页搜索结果（例如某一轮是经第三方网关回答的）时每个请求都报 400；修复更多继续或恢复（<code>--continue</code>、<code>--resume</code>）的会话把早先的消息以改动过的形式重发、导致 API 丢弃 Claude 之前的推理；修复 Claude 工作时用了 <code>/model</code>、<code>/rename</code>、<code>/artifacts</code> 等立即执行的斜杠命令后丢掉之前的扩展思考，以及用少了某个早先提供过的内置工具的 <code>--tools</code> 列表重新启动时丢失之前的扩展思考。</li><li>修复会话每一轮都因「Invalid <code>data</code> in <code>redacted_thinking</code> block」API 错误失败（现在丢弃对话里的思考块并重试一次）；修复总结请求被拒绝时压缩失败（改在回退模型上重试）；修复关闭思考、强度高于 high 的会话在安全相关的模型切换后，本轮以「Effort &#39;xhigh&#39; isn&#39;t available with thinking turned off」失败。</li><li>Fable 与登录：SDK 宿主的会话（如 Claude Desktop）里没人回应 Fable 用量额度提示时不再擅自切换模型（本轮直接结束，Remote Control 客户端也能看到换模型的通知）；套餐需要尚未开通的用量额度时，<code>/model</code> 加完整的 Fable 模型 id 会打开额度提示，而不是停在 API 错误；另一个进程在刷新登录中途被关掉或杀掉后，请求不再在最长一分钟里报「another Claude Code process is refreshing it」；另一个窗口正在刷新登录时启动的会话（开着多个 VS Code 窗口时常见）会重试组织策略拉取。</li><li>修复 Bash 与 PowerShell 把磁盘配额写满藏在「Exit code 1」后面，并在临时目录留下大体积输出文件；修复工具入参校验错误只点名一个未知、缺失或类型错误的参数（同一调用里其它不合法的参数现在一并列出）；修复终端的 bracketed paste 模式中途被重置后，粘贴的多行文本被逐行提交；修复远程会话的 worker 重启后，在恢复的权限提示上批准的命令执行两次。</li><li>修复 <code>claude remote-control --debug</code> 报「Unknown argument: --debug」（Remote Control 自己的资格报错却让你加 <code>--debug</code> 运行）；修复在把 <code>ctrl+enter</code> 当成换行发送的终端上（Windows Terminal 1.25 之前）立即发送的提示仍写 <code>ctrl+enter</code>（现在显示 <code>ctrl+x ctrl+s</code>）；修复 <code>/install-github-app</code> 显示「cancelled」之后仍推送分支、保存 API Key 密钥；修复 Bedrock、Vertex 等第三方提供方上 <code>/feedback</code>、<code>/bug</code>、<code>/share</code> 在保存时取消仍会存下报告文件。</li><li>修复插件卸载在设置文件仍启用它或读不了时报告成功并删掉插件保存的选项（现在中止并点出文件）；修复卸载后读不到已装插件列表时删掉插件保存的选项与密钥（现在保留并说明）；Vertex AI 上 Claude Code 还不认识的模型（如刚发布的）也能用网页搜索；Amazon Bedrock 与 Bedrock Mantle 上的安全拦截消息会显示请求 ID 与消息 ID。</li><li>体验：恢复超大会话（包括从没压缩过的）更快；Windows 上会话记录文件读不了（EBADF）导致无法恢复时，报错会列出可能原因与处理办法；<code>/artifacts</code> 的标题对齐成一列，放不下的信息整段省略而不是从词中间截断，并支持 PgUp/PgDn、Home/End、滚轮与点击；随附的 <code>claude-api</code> 技能更新了拒答计费说明（输出前的拒答计入速率限制，流式中途的拒答按正常价格计费），并推荐用 <code>ant apply</code> 把 Managed Agents 资源作为版本化文件管理。</li><li>界面修复：在 <code>/skills</code> 里紧跟 <code>/</code> 输入的按键会进搜索框，打字时光标不再跳到技能列表（输入法的文字也不会落错位置）；非全屏模式下带滚动条的列表不再窄两列；全屏启动时首帧之前不再闪白屏，有 <code>SessionStart</code> hook 的项目启动时输入框的示例文字不再一闪而过；diff 里重绘的行中 CJK 字符或表情折到下一行时，最后一列不再留下残字；Claude 给 artifact 版本起的标签超过 60 个字符时自动截短，发布不再失败；<code>/effort</code> 与输入框里 <code>ultracode</code> 的视觉效果改为朴素样式，并去掉动态工作流的 spinner 提示；vim 模式修正 <code>&gt;&gt;</code>、带计数的 <code>r</code>、<code>2J</code>、<code>.</code> 前的计数等一批行为。</li></ul><p><strong>v2.1.281</strong></p><ul><li>🆕 <strong><code>&quot;attribution&quot;: false</code></strong>：在 <code>settings.json</code> 里一行隐藏所有 commit 与 PR 署名。更早的版本读到它会跳过整份 settings 文件，跨版本共用的文件请继续用对象写法（<code>commit</code>、<code>pr</code> 设为空字符串，<code>sessionUrl</code> 设为 <code>false</code>）。</li><li>🆕 <strong><code>--agents</code> 可以传 JSON 文件路径</strong>（配合 <code>-p</code>），适合命令行放不下的大段 subagent 定义；定义里的 <code>prompt</code> 也允许为空。</li><li>🆕 <strong>MCP URL 模式的 elicitation</strong>：在 2026-07-28 协议的连接上，服务器可以请 Claude Code 打开一个基于浏览器的流程；服务器无法确认完成时，屏幕上不会留下一个等待中的对话框。</li><li>🆕 <code>claude plugin validate</code> 新增 MCP 服务器检查：报告加载时会被静默丢弃的 <code>.mcp.json</code> 条目、未声明的 <code>${user_config.*}</code> 引用与不安全的 URL；shell 形式的 hook 没给 <code>${CLAUDE_PLUGIN_ROOT}</code> 加引号时告警（插件路径含空格就会出错），插件 hook 失败时报错会点名是哪个插件。</li><li>🆕 <code>/insights</code> 新增 auto mode 建议，估算最近的会话里有多少权限提示本可以由 auto mode 处理；全屏模式下 <code>/skills</code>、<code>/mcp</code> 与 <code>/plugin</code> 的 Installed 列表加上滚动条（和 <code>/workflows</code> 一样，鼠标悬停时出现，可以点击或拖动）。</li><li>🆕 Claude apps 网关：Bedrock 上游支持 <code>assume_role</code>（经 STS 以 IAM 角色调用 Bedrock，可跨 AWS 账号，可选每位开发者一个会话）与 <code>guardrail: {id, version}</code>（给经过的每个请求套用 Amazon Bedrock guardrail，要么所有 Bedrock 上游都设、要么都不设）；新增 <code>telemetry.resource_attributes</code>，给 Claude Desktop 与 <code>/login</code> 会话的遥测打上固定标签；<code>desktop</code> 策略块支持更新的 Claude Desktop 键，包括 <code>blockReadsOutsideWorkingDirectories</code> 与 <code>disableBypassPermissionsMode</code>；<code>managedMcpServers</code> 条目的 <code>envHelper</code> 路径以 <code>\\??\\</code> 或 <code>/??/</code> 开头时网关拒绝启动。</li><li>⚠️ <strong>立即发送（<code>ctrl+enter</code> 或 <code>ctrl+x ctrl+s</code>）不再取消这一轮</strong>，而是把正在运行的工具转入后台，Claude 在同一轮里读到你的消息。</li><li>⚠️ <strong>危险 <code>rm</code> 的确认加上时限</strong>：<code>--dangerously-skip-permissions</code> 与 auto mode 下最多等 2 分钟，无人回答就拒绝并附上改写提示，让无人值守的会话能继续跑（<code>CLAUDE_CODE_DISABLE_DANGEROUS_RM_TIMEOUT=1</code> 关闭）；目标只是命令替换输出的递归 <code>rm</code>（如 <code>rm -rf &quot;$(pwd)&quot;</code>）在这两种模式下不再不经询问就执行，即使有 Bash allow 规则也会询问（<code>CLAUDE_CODE_DISABLE_SUBSTITUTION_RM_PROMPT=1</code> 关闭）；危险 <code>rm</code> 检查还会标记删除「shell 变量加顶层目录名」、由工作目录派生的变量，以及只有反斜杠的目标。</li><li>⚠️ <strong><code>CLAUDE_CODE_AUTO_MODE_SERVER</code> 也作用于直连 Anthropic API</strong>：<code>0</code> 退出服务端分类器（本地分类器的请求计入用量），<code>1</code> 启用；服务端审查的会话里，只读与沙箱化的 shell 命令也要等审查结果，被标记就拦下。</li><li>⚠️ <strong><code>AGENTS.md</code> 支持扩展到 Amazon Bedrock、Google Vertex AI、Microsoft Foundry、LLM 网关以及关闭遥测的会话</strong>。</li><li>⚠️ <strong>自托管运行环境改用私有文件把系统提示词交给 Claude Code</strong>，不再放在命令行里，大段提示词不会再导致启动失败；包装脚本或 <code>command</code> hook 里追加 <code>--system-prompt</code> / <code>--append-system-prompt</code> 的，要改用 <code>--system-prompt-file</code> / <code>--append-system-prompt-file</code>。</li><li>⚠️ 提示框下方的会话 artifact 链接合并成一个页脚标签（<code>⧉ name</code> 或 <code>⧉ N</code>），点开即 <code>/artifacts</code>，列表里本会话的 artifact 排在最前；Artifact 工具允许 Claude 在 artifact 页面里加载 unpkg.com 上的脚本；排队中的消息改为显示在对话里 spinner 的上方；在 <code>/tasks</code> 里对运行中的 <code>/ultrareview</code> 按 <code>x</code> 会先确认再停止。</li><li>⚠️ MCP 资源列表（资源列表工具与 <code>@</code> 提及建议）跳过 MCP Apps 的 UI 资源，按 URI 读取仍然可以；Remote Control 下载附件时复用连接、跳过本会话已下载过的文件；插件文件夹因另一个已装插件在用、或安装记录读不了而保留时，<code>claude plugin uninstall --json</code> 与 <code>/plugin</code> 对话框会说明数据被保留；命令菜单与 <code>/help</code> 里去掉残留的「(removed)」<code>/agents</code> 条目（直接敲 <code>/agents</code> 仍会说明向导去哪了）。</li><li>⚠️ 列表界面统一：全屏模式下鼠标悬停的行改为着色，不再在焦点行之外多画一个 <code>❯</code>（<code>/config</code> 也一样）；<code>/mcp</code> 每行以状态图标与名称开头、状态只说一次，窄终端里先省掉「managed」这类尾部信息再截短名字；<code>/workflows</code> 每行以状态图标与已运行时间开头，窄终端保留名称与时间，先省掉 agent 与 token 数。</li><li>安全：修复权限对话框与附件检查在批准之前就读取 macOS <code>/.vol</code>、<code>/.nofollow</code>、<code>/.resolve</code> 下（可能通往网络挂载）的路径；修复含 NUL 字节的权限规则被展开成通配匹配（现在什么都不匹配）；修复 <code>claude --bg</code> 在未通过工作区信任确认的目录里启动后台会话并运行项目 hook（现在先请求信任，非交互运行时直接退出）；修复 <code>--setting-sources</code>（以及 SDK 的 <code>settingSources</code>）没有传给派生的会话，队友、<code>/bg</code>、<code>claude agents</code> 会话与 <code>--worktree --tmux</code> 现在都沿用父会话的限制；<code>--channels</code> 的插件条目除了 marketplace，已装插件的名字也必须匹配。</li><li>沙箱：<code>excludedCommands</code> 条目现在能匹配 <code>git rev-parse --git-dir</code>、与 shell 内建命令同名的程序，以及含 <code>[WIP]</code> 或 <code>#</code> 行的提交信息；设了 <code>CLAUDE_CODE_TMPDIR</code> 时，沙箱化的 Bash 命令能写 <code>$TMPDIR</code>；macOS 上本地开发服务器绑不了端口时，Claude 会指向 <code>sandbox.network.allowLocalBinding</code>。</li><li>恢复会话一批修复：恢复的会话不再把早先的轮次以改动过的形式重发（并行工具调用的一轮、服务器重连期间的 MCP 工具入参或 tool search 结果等），避免 API 丢弃之前的推理；超大会话恢复时不再只恢复最后几条消息；权限提示未决时重启、之后再恢复，不再发出不同的历史而击穿 prompt 缓存；在工具调用中途结束的会话恢复后，Claude 能看到这次调用并被告知结果未知，手动恢复也不再追加隐藏的「Continue」消息。</li><li>代理与网关一批修复：被代理或网关干净地提前关闭的流不再被当成完整回复而毫无告警，重复的流事件也不再让工具调用执行两次；代理丢掉流事件时不再报「Content block not found」（保留已收到的部分回复，网页搜索也保留已到的结果）；代理在末尾补发只含用量的帧时不再丢失 stop reason；连接在最终事件前断开时不再把空的完成回复请求两次；关闭 tool search 时（如走代理或网关），MCP 服务器在对话中途断开、或恢复后仍在连接，不再让 prompt 缓存失效。</li><li>重试与崩溃：修复重试 API 请求期间可能以「unrecoverable interface error」崩溃、结束会话；修复模型交替输出无法解析的工具调用与超长截断时，一轮无视 <code>--max-turns</code> 无限重试；修复 <code>CLAUDE_CODE_RETRY_WATCHDOG</code> 会话在一连串 429/529 等待后遇到第一个 5xx 或断线就失败，以及对 5xx 的超长 <code>Retry-After</code> 无上限地静默等待；修复 fast mode 在服务器发来 <code>Retry-After: 0</code> 时背靠背重试被限流的请求；修复较早的 advisor 结果 API 读不了时每轮都有一个请求失败、反复丢失推理（现在一次性修复历史）。</li><li>工具修复：返回超大图片的工具不再让同批的其它工具调用无人应答、继续运行，或让本轮没有最终消息就结束；模型用超长名字调用工具后，对话不再永久卡在「tool_use.name: String should have at most 200 characters」；读不到自身内存用量（如文件描述符耗尽）时，工具调用不再以「Failed to get memory usage」失败；Read、Write、Edit、NotebookEdit 遇到含 NUL 字节的路径只让这次调用失败并给出清楚的错误，不再结束整轮；Write 在两个参数名下给出相同的路径或内容时不再拒绝。</li><li>无头与 SDK：之前的 assistant 消息是纯字符串内容时，<code>--input-format stream-json</code> 会话（Agent SDK、VS Code 扩展）与定时的云端会话不再每轮报错；启动目录在会话中途被删后，非交互会话（<code>-p</code>、Agent SDK）的下一轮不再失败；宿主（SDK）侧的 MCP 服务器握手中途失去响应时，首条消息不再卡住（远程会话最多等几秒）；工作目录内的 <code>--add-dir</code> 目录里的 CLAUDE.md 与规则文件不再在无头与 SDK 会话里发给模型两次。</li><li>启动与性能：没有配置 MCP 服务器或插件时，交互式启动不再等托管设置的网络请求（约 80 毫秒，网络不通时 17 秒以上）；托管设置与策略拉取不再重试注定失败的请求；git 读取、启动遥测与 Bedrock / Vertex 的模型升级检查不再挡在首帧之前；恢复读过很多文件的长会话、以及压缩过的超长会话都更快（经 Agent SDK 与 Claude Desktop 时最明显）；读取或 <code>@</code> 提及大于 3 MB 的 PDF 不再最多延迟两分钟，中断读取指定 PDF 页面后，渲染也不再继续跑最多两分钟。</li><li>auto mode 与压缩：在新进程里恢复会话后，权限分类器可以复用之前的 prompt 缓存，不必重写；拒绝消息让 Claude 明白被拒的是这个结果本身，而不只是这一条命令；一份超大的首条提示词占据大半会话时，「Prompt is too long」恢复会单独总结它，而不是把它排除在摘要之外。</li><li>远程与定时：定时任务与 <code>/loop</code> 的唤醒投递失败时不再每秒重发（此前可能让 Claude Code 在一轮结束时退出）；组织策略还没加载完时，Remote Control 不再报「disabled by your organization&#39;s policy」（改为重试并说明无法验证）；<code>claude remote-control</code> 为你启动、供 Claude Desktop、claude.ai 或移动端打开的会话里不再缺少 Artifact 工具；远程会话里定时 routine 与通知触发的轮次，在首个工具调用之前就能收到轮次开始通知（新可用的工具、MCP 变化、日期、todo）；权限提示与沙箱网络访问提示重叠并都回答后，远程会话不再停在「needs approval」。</li><li>登录与 MCP：登录钥匙串锁定时（如刚唤醒），macOS 写凭证不再丢掉已存的 MCP OAuth token 或删掉钥匙串条目；Claude Code 退出或刷新超时后不再留下 <code>gcpAuthRefresh</code> / <code>awsAuthRefresh</code> 登录进程（Windows 上还占着本地回调端口）；从另一个 Claude Code 进程登录后，「Not logged in · Run /login」页脚与缺失的 claude.ai connector 不再残留；阻断型事件（如 PreToolUse）上的 <code>mcp_tool</code> hook 在 MCP 服务器还在连接时不再被跳过，而是最多等到 MCP 连接超时；插件或 claude.ai connector 与配置的服务器 URL 写法不同（主机大小写、默认端口、结尾斜杠）时，不再重复连接同一个服务器；<code>MCP_CONNECTION_NONBLOCKING=0</code> 不再 1 秒就放弃 claude.ai connector，而是遵守 <code>MCP_CONNECT_TIMEOUT_MS</code>。</li><li>插件：<code>--plugin-dir</code> 指向同时带 <code>.claude-plugin/marketplace.json</code> 的插件文件夹时，不再只加载出一个空插件；<code>claude plugin uninstall</code> 能卸载未启用的项目级插件；省略 <code>--scope</code> 时，<code>claude plugin update</code> 按插件实际的安装作用域更新项目级插件；<code>claude plugin validate</code> 不再把 <code>plugin.json</code> 里 <code>privacyPolicyUrl</code>、<code>supportUrl</code> 等上架元数据键报成未知字段；远程不可达、<code>CLAUDE_CODE_PLUGIN_KEEP_MARKETPLACE_ON_FAILURE</code> 保留了旧克隆时，<code>known_marketplaces.json</code> 不再把 marketplace 记成已刷新。</li><li>对话框与按键：<code>/permissions</code> 删除规则、移除目录的确认框里指针在 No 上时，按 <code>1</code> 不再答成 Yes（此前按住 <code>1</code> 会一个接一个地删掉工作目录）；在无法关闭思考的模型上，Alt+T 与 <code>/config</code> 不再提供关闭思考的开关（改为一行说明原因）；快速按两次 Shift+Tab 不再落到错误的权限模式；<code>/memory</code>、<code>/hooks</code>、<code>/mcp</code>、<code>/export</code>、<code>/copy</code>、<code>/theme</code> 等其余对话框与选择器里连按两次 Ctrl+C 或 Ctrl+D 只关闭对话框，不再退出 Claude Code；一次性到达的一串按键（如经 Remote Control）不再作用于之前的选中项。</li><li>其它修复：<code>/context</code> 的总量算上上次回复之后新增的消息（因此可能比状态栏显示的高）；API 拒绝所选模型时，<code>/model</code> 显示服务器的说明并告知模型没有更换，而不是原始 JSON 与请求 ID；来自 HTML 错误页（如代理的 429 或 502 页面）的 API 错误不再打印原始标记或漏掉 HTTP 状态码；<code>/feedback</code>、<code>/bug</code>、<code>/share</code> 在发送中取消后不再照发；<code>/setup-bedrock</code> 或 <code>/setup-vertex</code> 重启 Claude Code 应用新设置后，终端不再处于损坏状态；Bash 编辑 diff 的快照目录不再在临时目录里堆积；Windows 上同时更新的会话不再可能互删 <code>claude.exe</code> 备份、最后连一个 <code>claude.exe</code> 都不剩，写入 <code>$TMPDIR/…</code> 的 Bash 命令也不再报「Permission denied」。</li><li>改进：<code>/batch</code> 在由 WorktreeCreate hook 提供 agent worktree 的环境里也能运行，不再限于 git 仓库；<code>/</code> 菜单、<code>/skills</code>、<code>/context</code> 与 <code>/plugin</code> 的 Installed 列表在没有冲突时用短名显示从 claude.ai 同步的技能，而不是 <code>anthropic-skills:&lt;name&gt;</code>；大 CLAUDE.md 的启动提示把多份说明文件合起来计算，许多中等大小的文件与 <code>@</code> 导入也会被发现；调试日志会点名因启动环境已设置而被忽略的 settings <code>env</code> 变量；<code>/deep-research</code> 在长研究任务书上更可靠；随附的 artifact-design 技能要求 Claude 在发布的页面里用平实直接的文字，慢速网络下大页面改为压缩上传。</li><li>界面：提示框下方的后台工作流行显示名称、进度条、agent 数（宽终端）、已运行时间、总 token 数与大规模工作流告警；<code>/workflows</code> 与 <code>/mcp</code> 列表支持翻页（PgUp/PgDn、Home/End）、j/k 与鼠标，方向键跟随 <code>select:previous</code> / <code>select:next</code> 的重绑定，<code>/workflows</code> 里按 <code>x</code> 停止指针所在的运行；<code>/skills</code> 每行以技能名开头，只用 ✔ 或 ◯ 表示开关；<code>/plugin</code> 的 Installed 列表各段按列对齐；<code>/diff</code> 的长文件列表带滚动条；<code>/hooks</code> 的详情页会说明这是哪种 hook、该到哪里改；<code>/permissions</code>、<code>/usage</code> 等分页对话框里 ↑/↓ 在标签行与内容之间移动焦点；<code>/install-github-app</code>、<code>/desktop</code> 等提示改用带按键提示的标准对话框框架，第二次按 Ctrl+C 或 Ctrl+D 取消。</li></ul><p><strong>v2.1.280</strong></p><ul><li>🆕 <strong>Claude Opus 5.5</strong>（<code>claude-opus-5-5</code>）发布并成为默认 Opus 模型：1M 上下文，$4/$20 每 Mtok，缓存读取 $0.20/Mtok。按官方文档，它的默认推理强度是 <code>medium</code>（比 Opus 5 的 <code>high</code> 低一档），并且和 Fable 模型一样无法关闭思考。</li><li>⚠️ <strong>Pro 与 Team Standard 套餐的默认模型从 Sonnet 改为 Opus</strong>，与 Max、Team Premium、Enterprise 一致。</li><li>⚠️ <strong>推理强度的两处调整</strong>：<code>/effort</code> 改为按模型保存之前存下的强度，不再套用到 Opus 5.5 这类新发布的模型，它们从自己的默认强度起步，直到你选一个；Opus 4.7、Opus 4.8 与 Fable 5 不再用发布时的默认强度压过 <code>-p</code> 或 Agent SDK 里的 <code>/effort</code>、项目 / 托管 / <code>--settings</code> 里的 <code>effortLevel</code>，以及按模型保存的强度。</li><li>🆕 <code>CLAUDE_CODE_MAX_MCP_DESCRIPTION_LENGTH</code>：调整会话里所有 MCP 服务器的工具描述与服务器说明的 2048 字符上限；<code>hook_execution_complete</code> OTel 事件新增 hook 输出的大小，以及超长输出被存成文件的个数。</li><li>🆕 全屏模式下更多列表支持鼠标：滚轮滚动 <code>/skills</code> 列表，<code>/plugin</code> 里技能的状态选项可以点击，有隐藏选项的选择列表（如 <code>/model</code>、<code>/permissions</code>）也能用滚轮滚动；<code>/config</code> 设置列表与 <code>/model</code>、<code>/memory</code>、权限提示等选择列表支持 Home / End。</li><li>⚠️ <strong><code>y</code> / <code>n</code> 不再默认确认或关闭对话框</strong>：统一用 Enter 与 Esc 确认、取消，误按的 <code>y</code> 或 <code>n</code> 不会再替你做决定（想找回就在 <code>keybindings.json</code> 里把 <code>y</code>、<code>n</code> 绑到 <code>confirm:yes</code>、<code>confirm:no</code>）；对话框里的文本框不再把输入的字母、数字或空格让给该键上的快捷键；<code>/model</code>、<code>/effort</code>、<code>/config</code>、<code>/status</code>、<code>/usage</code>、<code>/plugin</code>、<code>/permissions</code> 等大多数对话框里连按两次 Ctrl+C 或 Ctrl+D 只关闭对话框，不再退出 Claude Code。</li><li>⚠️ <strong><code>PermissionRequest</code> 事件上不再运行 agent 型 hook</strong>（它的回答本来就无法批准或拒绝请求），改为报错并指向 command 或 http hook。</li><li>⚠️ 名字模仿保留 marketplace 名的插件 marketplace 在添加时被拒绝，已经添加的也会停止加载；撤回 2.1.260 起全屏模式下 <code>ctrl+l</code> / <code>cmd+k</code> 清空 transcript 视图的做法，它们重新只重绘屏幕；<code>/autocompact</code> 的页脚提示改为说明 ←/→，<code>/fast</code> 的页脚写明用空格切换。</li><li>⚠️ 自托管运行环境：生命周期 hook 里的 git 忽略运行环境共享 git 文件里指定的 hook 目录与程序，那里的本地路径与 <code>git://</code> 远程需要 <code>GIT_ALLOW_PROTOCOL</code>；另修复 <code>--configure-git</code> 下生命周期 hook 的提交签名失败，以及一轮恰好在 <code>--retire-at</code> 发布点结束时丢失完成信号。</li><li>安全：修复经符号链接路径的写入按它在工作树里的写法判定——现在提示会说明实际落在哪里，<code>acceptEdits</code>、allow 规则与 auto mode 不再批准落在外面的写入；<code>/ultrareview</code> 上传时，重命名过的关键文件副本（如 <code>id_rsa copy</code>、<code>kubeconfig (1).yaml</code>）同样留在本机。</li><li>auto mode：安全检查拒绝审查某个操作时，不再一遍遍重试（改为拒绝一次并说明重试无用）；安全检查没给出答复时，不再不停地连续拒绝（改为退避重试，连续十次后停下本轮并说明）。</li><li>修复会话每轮都报「role &#39;system&#39; must precede an &#39;assistant&#39; message」API 错误；修复代理或网关不支持 advisor 时，开着 advisor 的会话每轮都以 API Error 400「Input tag &#39;advisor_20260301&#39;」失败（现在去掉它重试）；修复保存的历史里有格式错误的「MCP 工具无法加载」通知时，每轮与 <code>/compact</code> 都失败；修复恢复带格式错误系统消息、或缺文件列表的记忆保存通知的会话时崩溃；修复长时间运行的全屏会话以「unrecoverable interface error」退出的一个原因（损坏的消息列表缓存现在会重建）。</li><li>后台任务：恢复带未完成后台 agent、shell 或工作流的会话时，不再没等你输入就自己开始一轮；无头与 SDK 会话里发给正在收尾的后台 subagent 的消息不再静默丢失；启动 subagent 的对话在读取报告前被压缩时，已完成 subagent 的报告不再丢失；LSP 插件启用时，后台 subagent 可以用 LSP 工具；后台 shell 任务的良性非零退出（如 grep 没有匹配）不再被报告成失败；后台 subagent 运行时按两次 Ctrl+C 即可退出（此前要三四次）。</li><li>prompt 缓存：恢复的 fork subagent 改为重发它最初用的工具列表，而不是重建一份导致缓存失效；Claude 工作时从宿主应用（Claude Desktop、VS Code、SDK）切换模型，不再让下一条提示词的 prompt 缓存未命中；<code>/cost</code> 的缓存未命中原因会点名思考模式与思考显示方式的变化。另修复 subagent 交还消息在非 verbose 模式下展开时露出内部的来源说明前言。</li><li>修复模型把参数写成 <code>path</code>、<code>file_text</code>、<code>file_content</code> 或多带一个 <code>description</code>（而不是 <code>file_path</code> 与 <code>content</code>）时 Write 调用校验失败；修复设置文件、或编辑后重读的文件在读取中途被换成命名管道时 Claude Code 挂起；修复已迁到 <code>settings.json</code> 的偏好在 <code>~/.claude.json</code> 里仍是 <code>null</code> 或 <code>&quot;false&quot;</code> 时 <code>/config</code> 崩溃、部分开关被误读；修复 <code>claude --bg</code> 会话在传入的环境变量含 NUL 字符时无法运行 git、hook、插件等辅助程序。</li><li>插件与技能：从跟踪分支或 tag 的 GitHub 仓库或 git URL 更新插件后，<code>installed_plugins.json</code> 不再保留安装时的提交；<code>~/.claude/skills/</code> 里的 <code>manifest.json</code> 列出技能名时，这些技能不再被挪进 <code>~/.claude/skills/.trash/</code>；后台 marketplace 自动更新遵守 git 凭证 helper，私有仓库的 marketplace 不再每次重新克隆或永远不更新；官方 marketplace 的快照文件是链接或过大时，<code>claude plugin update</code> 不再清掉插件记录的提交、把版本变成「unknown」；<code>claude mcp remove</code> 后以同名重新添加的 MCP 服务器会直接重连，不再显示需要认证。</li><li>Artifact：组织策略加载不了（如在网页代理之后）时 Artifact 工具不再悄悄消失，Claude 会说明是什么挡住了它；重新发布时漏发数据库访问规则或 viewer profile 范围的，不再静默重置，而是被拒绝；Claude 读不了收到的 artifact 链接时会先告诉你再继续；artifact 页面去掉打印按钮、确认对话框与查看者会屏蔽的设备功能，邮箱与电话显示为文本，暗色模式覆盖到表单控件与滚动条。</li><li>输入与语音：Windows 终端里按 Enter 移除不可见字符后，提示词行不再保持错乱（屏幕会重绘，让你审阅的正是将要发送的文本）；不可见字符清理不再移除波斯语、阿拉伯语用来把后缀接到拉丁词或数字上的零宽非连接符；语音听写按 Ctrl+C 会停止录音，处理转写时按 Esc 能取消；发出去的提示词回到输入框时（如按 Esc 编辑、rewind 回来）不再丢掉 IDE 选区；用 Ctrl+S 暂存的 <code>!</code> shell 模式提示词恢复后仍是 shell 模式；只是把终端窗口带到前台的那次点击，不再同时触发指针下的项目。</li><li>其它：<code>/ultrareview</code> 不再把停止的云端评审报告成已完成或可重试的错误，会话被删或登录账号变了也不再干等到超时；临时目录已满、不可写或属于别的用户时，<code>claude agents</code> 显示错误，而不是空白无响应的界面；Windows 上后台清理不再删掉用来搬迁 <code>~/.claude/session-env</code>、<code>image-cache</code> 等目录的目录符号链接或 junction；云端与自托管运行环境会话在长时间过载、访问 token 期间被轮换后，不再以「Authentication failed」失败。</li><li>改进：<code>/permissions</code> 查看、添加或删除规则后焦点回到规则列表，删除规则与移除目录的确认默认选 No，规则列表里按 ←/→ 或 Tab 直接切换标签页；没标语言的代码块改为按行内代码着色，命令更醒目；工具还在运行时问 <code>/btw</code>，旁支问题知道这次调用正在进行，不再当成失败；UserPromptSubmit hook 超时的提示与调试日志会点名是哪条 hook 命令；<code>@</code> 文件建议里文件名包含查询词的，排在只有目录名匹配的前面；<code>/artifacts</code> 与 <code>/workflows</code> 的长列表右边缘显示滚动条；跨会话消息的启动告警说明 <code>--debug-file</code> 会把调试日志写到你指定的路径。</li></ul><p><strong>v2.1.278</strong></p><ul><li>⚠️ <strong>auto mode 默认改用服务端分类器</strong>：Claude API 与 Enterprise 用户，以及 Bedrock、Vertex、Foundry 与网关上，auto mode 默认由服务端分类器审查，分类器的开销不再收费（取代 2.1.273 在 Bedrock、Vertex、Foundry 上暂时默认本地分类器的做法；这些平台与网关上可用 <code>CLAUDE_CODE_AUTO_MODE_SERVER=0</code> 退出）；回落到计费的本地分类器请求时会给出提示，说明见官方 <a href="https://code.claude.com/docs/en/auto-mode-classifier-billing" target="_blank" rel="noreferrer">Auto mode classifier request charges</a>。</li><li>🆕 <code>/status</code> 新增「Auto mode server」一行，显示本会话的 auto mode 分类器是否跑在服务端。</li></ul><h2 id="v2-1-270-→-v2-1-277-速览" tabindex="-1">v2.1.270 → v2.1.277（速览） <a class="header-anchor" href="#v2-1-270-→-v2-1-277-速览" aria-label="Permalink to &quot;v2.1.270 → v2.1.277（速览）&quot;">​</a></h2><p>这一段是手册上一版覆盖的最后一批版本，只保留影响较大的变化：</p><ul><li><strong>v2.1.277</strong> —— 🆕 项目里没有 <code>CLAUDE.md</code> 时改读 <code>AGENTS.md</code>（<code>/config</code> 的「Project instructions」可改）、<code>CLAUDE_GATEWAY_PROXY_IS_EGRESS_BOUNDARY</code>；⚠️ 移除 TaskOutput 工具，<code>taskOutputMaxChars</code> 与 <code>TASK_MAX_OUTPUT_LENGTH</code> 随之失效；subagent 的结果放在标明「subagent 输出」的标头下交给主 agent；提示词里不可见的 Unicode 格式字符与标签字符会被移除；<code>sandbox.excludedCommands</code> 要求复合命令的每一段都匹配才豁免。</li><li><strong>v2.1.276</strong> —— 修复 2.1.275 引入的回归：<code>ANTHROPIC_BASE_URL</code> 指向代理或网关时，每个请求都报 <code>Input tag &#39;advisor_20260301&#39;</code> 的 400。</li><li><strong>v2.1.275</strong> —— 🆕 立即发送键 <code>ctrl+enter</code>（或 <code>ctrl+x ctrl+s</code>）、同步 claude.ai 账号上的技能与插件（<code>syncClaudeAiSkills</code> / <code>syncClaudeAiPlugins</code> 可退出）、<code>/plugin install &lt;plugin&gt; --marketplace &lt;source&gt;</code>；⚠️ npm 来源的插件改用 <code>npm pack --ignore-scripts</code> 拉取，不再运行安装脚本；<code>--system-prompt</code> 里 <code>__SYSTEM_PROMPT_DYNAMIC_BOUNDARY__</code> 一行之上的文本全局缓存。</li><li><strong>v2.1.274</strong> —— 🆕 <code>CLAUDE_CODE_MCP_STARTUP_WAIT_MS</code>、<code>OTEL_LOG_MANAGED_SETTINGS</code>、内存临界告警；⚠️ <code>/code-review</code> 对没有专属调优的模型改用精简的内联评审；Bedrock、Vertex、Foundry 与关闭遥测的安装也默认用 v2 MCP 客户端与 2026-07-28 协议协商；<code>&quot;type&quot;: &quot;sdk&quot;</code> 的 MCP 条目被跳过；插件与 marketplace 克隆不再下载 Git LFS 文件。</li><li><strong>v2.1.273</strong> —— 🆕 给 LLM 网关的提示请求头（<code>CLAUDE_CODE_GATEWAY_HINT_HEADERS=1</code>）、从 Claude App fork Remote Control 会话；⚠️ Bedrock、Vertex、Foundry 上的 auto mode 暂时默认用本地分类器（2.1.278 起又改为默认服务端）；撤回 2.1.268 把 Read / Edit deny 规则套到无法分析的 Bash 命令上的改动。</li><li><strong>v2.1.271</strong> —— 🆕 Remote 会话支持 fast mode、agent frontmatter 的 <code>omitClaudeMd</code>、沙箱 auto mode 下按命令放行的 <code>allowed_domains</code>、<code>claude plugin install</code> / <code>update</code> 的 <code>--accept-command &lt;sha256&gt;</code>；⚠️ Monitor 监视一律带时限（取代 <code>persistent</code>）；「中等」动态工作流规模降到 10 个 agent、Pro 套餐默认「小」，撞到用量上限改为暂停；auto mode 下 subagent 改用交还调用回报。</li><li><strong>v2.1.270</strong> —— 修复 2.1.269 引入的回归：会话运行一段时间后，Bash 里的只读 git 命令意外要求权限。</li></ul><h2 id="v2-1-224-→-v2-1-269-速览" tabindex="-1">v2.1.224 → v2.1.269（速览） <a class="header-anchor" href="#v2-1-224-→-v2-1-269-速览" aria-label="Permalink to &quot;v2.1.224 → v2.1.269（速览）&quot;">​</a></h2><p>更早一批版本，只保留影响较大的变化：</p><ul><li><strong>v2.1.269</strong> —— 🆕 <code>claude plugin eval</code> 插件评测、<code>/output-style [name]</code>、<code>bashEditDiffEnabled</code> 设置、<code>CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS</code>；⚠️ <code>!</code> 开头的 deny/ask 规则只在写它的 settings 来源内生效；云端会话里同步的技能改名为 <code>anthropic-skills:&lt;name&gt;</code>；<code>/ultrareview --post</code> 直接发 PR 评论。</li><li><strong>v2.1.268</strong> —— ⚠️ 任务追踪工具只在 Claude 3.x、Opus 4.0–4.7、Sonnet 4.0–4.6、Haiku 4.5 上提供（<code>CLAUDE_CODE_ENABLE_TODO_TOOLS=1</code> 找回）；<code>/plugin</code> 里的安装、启用、禁用在关闭菜单时即生效；普通的 <code>WebFetch</code> 规则不再管 Artifact 工具；🆕 <code>CLAUDE_CODE_WEBFETCH_DEADLINE_MS</code>，<code>claude plugin</code> 各子命令支持 <code>--json</code>。</li><li><strong>v2.1.267</strong> —— 🆕 <code>maxEffortLevel</code> 设置、<code>--system-prompt-snapshot off</code>；一大批 prompt 缓存稳定性修复。</li><li><strong>v2.1.265</strong> —— 🆕 <code>--plugin-dir</code> 可指向装了多个插件的文件夹；⚠️ 非交互会话里的 <code>cd</code> 跨轮保留。</li><li><strong>v2.1.261</strong> —— 🆕 <code>/skill-doctor</code>、<code>bashOutputMaxChars</code> / <code>taskOutputMaxChars</code>（后者 2.1.277 起失效）、<code>--append-subagent-system-prompt-file</code>；⚠️ 输入框的删词按键改为与 Bash 一致，<code>keybindingFlavor</code> 不再生效。</li><li><strong>v2.1.260</strong> —— 🆕 全屏 diff 面板（<code>/diff</code> 切换）、<code>/cost</code> 给出 prompt 缓存未命中的可能原因；⚠️ 撤回 2.1.259 把 <code>Read()</code> deny 规则套到 Bash 参数上的改动；<code>!</code> bash 模式里的命令在沙箱外运行。</li><li><strong>v2.1.259</strong> —— 🆕 <code>managedMcpServers</code> 托管设置、<code>--permission-prompts none</code>；⚠️ <code>allowedMcpServers</code> 只管用户自己添加的服务器；托管设置无法解析时拒绝启动。</li><li><strong>v2.1.257</strong> —— 🆕 <strong>Fable 5.1</strong> 发布，<code>timeFormat</code> / <code>timeZone</code>、<code>CLAUDE_CODE_SUBAGENT_MODEL_FORCE</code>；⚠️ 项目级设置里的 <code>defaultMode: &quot;bypassPermissions&quot;</code> 被忽略；<code>--add-dir</code> 拒绝网络路径。</li><li><strong>v2.1.251</strong> —— 🆕 <code>PreModelSwitch</code> / <code>PostModelSwitch</code> hook 事件；⚠️ <code>CLAUDE_CODE_SUBAGENT_MODEL</code> 改为默认值而非强制覆盖；<code>/effort</code> 按模型分别保存；项目级 <code>env</code> 不能再设 <code>CLAUDE_CONFIG_DIR</code> 等目录变量。</li><li><strong>v2.1.248</strong> —— 🆕 <code>--restricted</code> 受限模式、agent frontmatter 的 <code>experimental.cacheTtl</code>；⚠️ Workflow 工具描述瘦身，写脚本的参考资料移进 <code>workflow-authoring</code> 技能。</li><li><strong>v2.1.247</strong> —— 🆕 <code>SendFeedback</code> 工具、<code>/claude-api cost-optimize</code>；⚠️ Sonnet 5 的默认自动压缩窗口改为完整 1M。</li><li><strong>v2.1.246</strong> —— 🆕 <code>/permissions</code> 的 Auto mode 标签页；⚠️ <code>/cd</code> 后新目录的项目设置、hooks、技能与 agent 立即生效；subagent 撞到 <code>maxTurns</code> 时返回「部分完成」的输出。</li><li><strong>v2.1.243</strong> —— 🆕 <code>modelPicker</code>、<code>promptCacheTtl</code> / <code>subagentPromptCacheTtl</code>、<code>modelPricing</code> 托管设置；下载包改用 zstd 压缩（Linux x64 约 75 MB）。</li><li><strong>v2.1.239</strong> —— 🆕 跨会话消息支持 Windows、<code>/claude-api upgrade</code>；⚠️ 成本估算计入数据驻留工作区的 1.1× 溢价。</li><li><strong>v2.1.238</strong> —— 🆕 插件 marketplace 的 <code>headersHelper</code>；⚠️ 项目 <code>.mcp.json</code> 里的 <code>headersHelper</code> 与 agent 文件里的内联 MCP 服务器要求目录已通过信任确认。</li><li><strong>v2.1.237</strong> —— 🆕 内置「Concise」输出风格。</li><li><strong>v2.1.236</strong> —— 🆕 <code>ANTHROPIC_DEFAULT_MODEL</code>、跨会话 <code>SendMessage</code> 的 <code>notify_when_idle</code>；⚠️ 拼错的斜杠命令直接报错，不再跑模糊匹配。</li><li><strong>v2.1.235</strong> —— 🆕 <code>spellcheck</code> 设置。</li><li><strong>v2.1.234</strong> —— 🆕 用量上限重置后自动继续会话、<code>/goal</code> 主动检查后台工作的进度；⚠️ 从 <code>/config</code> 移除「Default teammate model」。</li><li><strong>v2.1.233</strong> —— ⚠️ 任务追踪工具在新模型上不再提供；🆕 <code>CLAUDE_CODE_TOOL_MEMORY_LIMIT</code>、<code>CLAUDE_CODE_WEBFETCH_CACHE_TTL_MS</code>。</li><li><strong>v2.1.232</strong> —— ⚠️ <strong>fork subagent 默认开启</strong>；🆕 输入框里 <code>@</code> 点名其它会话、<code>additionalMarketplaces</code> / <code>allowedMarketplaces</code> 别名。</li><li><strong>v2.1.229</strong> —— 🆕 marketplace 的 <code>command</code> 来源、<code>claude remote-control --continue</code>。</li><li><strong>v2.1.228</strong> —— ⚠️ Write 工具在新模型上可以覆写本会话还没读过的已有文件。</li><li><strong>v2.1.225</strong> —— 🆕 <code>SendMessage</code> 可以按名字主动联系你其它机器上的 Remote Control 会话。</li><li><strong>v2.1.224</strong> —— 🆕 <strong>自托管运行环境</strong>（<code>claude self-hosted-runner</code>）、<strong>跨会话 <code>SendMessage</code></strong>、<code>archive</code> 插件来源；⚠️ 取消单会话 200 个 subagent 的派生总数上限。</li></ul><h2 id="v2-1-213-→-v2-1-223-速览" tabindex="-1">v2.1.213 → v2.1.223（速览） <a class="header-anchor" href="#v2-1-213-→-v2-1-223-速览" aria-label="Permalink to &quot;v2.1.213 → v2.1.223（速览）&quot;">​</a></h2><ul><li><strong>v2.1.223</strong> —— ⚠️ <code>/review</code> 成为 <code>/code-review</code> 的别名；<code>/code-review</code> 不带强度时沿用上次的强度；<code>CLAUDE_CODE_DISABLE_1M_CONTEXT</code> 扩大到所有原生 1M 窗口的模型；🆕 marketplace 管控支持 <code>&quot;owner/*&quot;</code> 通配。</li><li><strong>v2.1.222</strong> —— ⚠️ 移除 <code>/ultraplan</code>；Remote Control 自动启动不能再由仓库级设置开启。</li><li><strong>v2.1.221</strong> —— ⚠️ <code>/fork</code> 新建独立 worktree；后台会话默认提交并推送以保住工作；<code>/plugin</code> 装的插件立即生效；🆕 沙箱凭证 <code>mode: &quot;mask&quot;</code>。</li><li><strong>v2.1.219</strong> —— 🆕 <strong>Opus 5</strong> 发布；⚠️ subagent 嵌套默认深度 3；动态工作流默认「中等规模」（少于 15 个 agent）；🆕 <code>workflowSizeGuideline</code>、<code>sandbox.network.strictAllowlist</code>、<code>DirectoryAdded</code> hook。</li><li><strong>v2.1.218</strong> —— ⚠️ <code>/code-review</code> 改为后台 subagent 运行；<code>context: fork</code> 技能默认后台；<code>/deep-research</code> 只在手动调用时启动；agent 文件名不许含 <code>:</code>。</li><li><strong>v2.1.217</strong> —— ⚠️ 并发 subagent 上限 20；<code>--max-budget-usd</code> 能拦住后台 subagent；🆕 表情 shortcode 自动补全。</li><li><strong>v2.1.216</strong> —— 🆕 <code>sandbox.filesystem.disabled</code>；长会话消息规范化开销不再随轮数二次方增长。</li><li><strong>v2.1.215</strong> —— ⚠️ Claude 不再自行调用 <code>/verify</code> 与 <code>/code-review</code>。</li><li><strong>v2.1.214</strong> —— ⚠️ hook <code>if:</code> 条件里单段 <code>dir/**</code> 只匹配 <code>&lt;cwd&gt;/dir</code>；<code>docker</code> 守护进程重定向标志需确认；🆕 <code>EndConversation</code> 工具。</li><li><strong>v2.1.213</strong> —— 🆕 <code>allowShortlineEdits</code> 设置。</li></ul><h2 id="v2-1-205-→-v2-1-212-速览" tabindex="-1">v2.1.205 → v2.1.212（速览） <a class="header-anchor" href="#v2-1-205-→-v2-1-212-速览" aria-label="Permalink to &quot;v2.1.205 → v2.1.212（速览）&quot;">​</a></h2><ul><li><strong>v2.1.212</strong> —— ⚠️ <code>/fork</code> 语义变更：复制成独立后台会话，原来的「会话内派生 subagent」改用新命令 <code>/subtask</code>；🆕 会话级上限：<code>WebSearch</code> 默认封顶 200 次、subagent 派生默认封顶 200 个；⚠️ Task 工具的 <code>mode</code> 参数弃用，subagent 直接继承父会话权限；安全修复：计划模式不再未经确认执行会改文件的 Bash 命令。</li><li><strong>v2.1.211</strong> —— 🆕 <code>--forward-subagent-text</code> 标志与同名环境变量；「always allow」规则改存到仓库根，git worktree 之间也持久生效。</li><li><strong>v2.1.210</strong> —— 🆕 Agent 工具加固，抵御经由 subagent 内容的<strong>间接提示注入</strong>；<code>ultracode</code> 关键词不再被 webhook / 转发的 PR 评论误触发。</li><li><strong>v2.1.208</strong> —— 🆕 屏幕阅读器模式（纯文本渲染）；🆕 <code>vimInsertModeRemaps</code> 设置（把 <code>jj</code> 映射成 Escape）与 <code>CLAUDE_CODE_PROCESS_WRAPPER</code>；安全：带子 shell 的毁灭性删除命令即使在 <code>--dangerously-skip-permissions</code> 下也弹确认。</li><li><strong>v2.1.207</strong> —— 🆕 auto mode 在 Bedrock / Vertex / Foundry 上免 opt-in 可用；⚠️ 这些平台上 Claude Platform 默认模型改为 Opus 4.8。</li><li><strong>v2.1.206</strong> —— 🆕 <code>/commit-push-pr</code> 对配置好的 push remote 自动放行 <code>git push</code>；<code>EnterWorktree</code> 进入 <code>.claude/worktrees/</code> 以外的 worktree 前先确认。</li><li><strong>v2.1.205</strong> —— 🆕 auto mode 新增规则：阻止篡改会话 transcript；<code>--json-schema</code> 遇到非法 schema 改为报错。</li></ul><h2 id="v2-1-190-→-v2-1-204-速览" tabindex="-1">v2.1.190 → v2.1.204（速览） <a class="header-anchor" href="#v2-1-190-→-v2-1-204-速览" aria-label="Permalink to &quot;v2.1.190 → v2.1.204（速览）&quot;">​</a></h2><ul><li><strong>v2.1.203</strong> —— 登录即将过期时提前预警；<code>/mcp</code> 的 <code>roots/list</code> 带上本次会话新增的工作目录。</li><li><strong>v2.1.200</strong> —— ⚠️ <code>AskUserQuestion</code> 对话框默认不再自动继续；默认权限模式展示名从 “default” 改为 “Manual”。</li><li><strong>v2.1.199</strong> —— 堆叠式技能调用最多一次加载 5 个前置技能；<code>CLAUDE_CODE_RETRY_WATCHDOG</code> 把瞬时错误默认重试提到 300 次。</li><li><strong>v2.1.198</strong> —— <strong>subagent 默认后台化</strong>；<strong>Claude in Chrome 正式 GA</strong>；新增 <code>/dataviz</code> 技能；<code>/run</code>、<code>/verify</code>、<code>/run-skill-generator</code> 三件套上线。</li><li><strong>v2.1.197</strong> —— <strong>Sonnet 5 发布</strong>，成为默认模型。</li><li><strong>v2.1.196</strong> —— 支持组织级默认模型；<code>.mcp.json</code> 里仓库自行批准的 MCP 服务器不再被 <code>claude mcp list</code>/<code>get</code> 静默启动。</li><li><strong>v2.1.193</strong> —— 新增 <code>autoMode.classifyAllShell</code>、OTel <code>assistant_response</code> 日志事件、bash 模式实时路径补全。</li><li><strong>v2.1.187</strong> —— 新增 <code>sandbox.credentials</code> 设置；远程 MCP 工具调用新增空闲超时 <code>CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT</code>。</li><li><strong>v2.1.186</strong> —— <code>claude mcp login/logout &lt;server&gt;</code> 支持单独对某个 MCP 服务器走 OAuth。</li></ul><h2 id="更早的重要节点" tabindex="-1">更早的重要节点 <a class="header-anchor" href="#更早的重要节点" aria-label="Permalink to &quot;更早的重要节点&quot;">​</a></h2><ul><li><strong>2.0.0</strong>：全新原生 VS Code 插件；引入 <code>/rewind</code> 检查点回滚。</li><li><strong>1.0.81 前后</strong>：推出输出风格（output styles），含内置的 “Explanatory”、“Learning” 教学向风格（该功能后续经历过一次弃用又恢复的反复，最终保留）。</li><li><strong>0.2.x 系列</strong>：项目早期阶段，OTel 支持初具雏形，<code>CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC</code> 等隐私类开关陆续加入。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Claude Code 的发布节奏很快（经常一天多个补丁版本），<code>autoUpdatesChannel</code> 设为 <code>stable</code> 可以避免第一时间踩到重大回归——细节见<a href="/Front2Full/manual/agent/claude-code/installation">安装与升级 · 配置发布渠道</a>。</p></div>',44)])])}const m=o(l,[["render",a]]);export{p as __pageData,m as default};
